window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s7-619","number":619,"surah":7,"verses":[107],"verseLabel":"الأعراف: 107","question":"لماذا وصف الحية هنا بـ﴿ثعبان مبين﴾، وفي طه بـ﴿حية تسعى﴾، وفي موضع بـ﴿كأنها جان﴾؟","answer":"هي حية في حقيقتها، وثعبان في عظمها، وكأنها جان في سرعة حركتها؛ فكل وصف يبرز جهة تلائم مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص175–182.","url":""}]},{"id":"s7-620","number":620,"surah":7,"verses":[107],"verseLabel":"الأعراف: 107","question":"لماذا اختير ﴿ثعبان﴾ في مواجهة فرعون والسحرة؟","answer":"اختير ﴿ثعبان﴾ في المواجهة لإظهار عظم الجرم والقوة أمام فرعون والسحرة، فلا يلتبس بسحر خفيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص175–182.","url":""}]},{"id":"s7-621","number":621,"surah":7,"verses":[107],"verseLabel":"الأعراف: 107","question":"لماذا وُصف الثعبان بـ﴿مبين﴾؟","answer":"﴿مبين﴾ أي ظاهر الثعبانية لا تخييل فيه ولا اشتباه، فالمعجزة حقيقة مشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص175–182.","url":""}]},{"id":"s7-622","number":622,"surah":7,"verses":[108],"verseLabel":"الأعراف: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿ونزع يده﴾ لا «وأخرج يده»؟","answer":"النزع إخراج بقوة وسرعة من موضع ملازم، فيصور إخراج اليد من الجيب فجأةً وظهور أمر خارق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص183–186.","url":""}]},{"id":"s7-623","number":623,"surah":7,"verses":[108],"verseLabel":"الأعراف: 108","question":"لماذا عطف معجزة اليد بالواو لا بالفاء؟","answer":"الواو تجمع آية اليد إلى آية العصا باعتبارهما حجتين مستقلتين، لا تجعل الثانية نتيجة للأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص183–186.","url":""}]},{"id":"s7-624","number":624,"surah":7,"verses":[108],"verseLabel":"الأعراف: 108","question":"لماذا أضاف اليد إلى موسى كما أضاف العصا إليه؟","answer":"الإضافة تؤكد أن اليد نفسها المعروفة تغير لونها على وجه خارق، كما كانت العصا المعهودة محل التحول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص183–186.","url":""}]},{"id":"s7-625","number":625,"surah":7,"verses":[108],"verseLabel":"الأعراف: 108","question":"لماذا تكرر تركيب المفاجأة: ﴿فإذا هي﴾؟","answer":"تكرار ﴿فإذا هي﴾ يجدد المفاجأة في الآية الثانية ويثبت أن اليد نفسها صارت بيضاء للناظرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص183–186.","url":""}]},{"id":"s7-626","number":626,"surah":7,"verses":[108],"verseLabel":"الأعراف: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿بيضاء﴾ من غير ذكر «من غير سوء» هنا؟","answer":"اقتصر هنا على ﴿بيضاء﴾ لأن السياق مقام عرض سريع للآيتين، وبيّنت مواضع أخرى أنها من غير مرض أو برص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص183–186.","url":""}]},{"id":"s7-627","number":627,"surah":7,"verses":[108],"verseLabel":"الأعراف: 108","question":"لماذا قيد بياض اليد بـ﴿للناظرين﴾؟","answer":"قيدها بالناظرين لأن بياضها آية ضوئية ظاهرة يدركها كل من يشاهدها، لا إحساسًا خاصًا بموسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص183–186.","url":""}]},{"id":"s7-628","number":628,"surah":7,"verses":[109],"verseLabel":"الأعراف: 109","question":"لماذا تولّى الملأ الجواب فقال: ﴿قال الملأ﴾ ولم يُذكر قول فرعون؟","answer":"حكى قول الملأ لأنه كان رأي الحاشية المتداول أو لأن فرعون قال لهم وقالوا له، فاختصر السياق المشاورة الجماعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص187–191.","url":""}]},{"id":"s7-629","number":629,"surah":7,"verses":[109],"verseLabel":"الأعراف: 109","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿الملأ من قوم فرعون﴾، وفي الشعراء: ﴿قال للملإ حوله﴾؟","answer":"في الأعراف نُسب الحكم إلى ملأ فرعون، وفي الشعراء صُوّر فرعون مخاطبًا من حوله؛ والمشهدان يكشفان تواطؤ الرأس والحاشية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص187–191.","url":""}]},{"id":"s7-630","number":630,"surah":7,"verses":[109],"verseLabel":"الأعراف: 109","question":"لماذا أضيف الملأ إلى قوم فرعون لا إلى فرعون نفسه؟","answer":"إضافتهم إلى قوم فرعون تبين أنهم أشراف قومه لا خاصته وحدهم، وأنهم يمثلون طبقة القيادة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص187–191.","url":""}]},{"id":"s7-631","number":631,"surah":7,"verses":[109],"verseLabel":"الأعراف: 109","question":"لماذا أكدوا قولهم بـ﴿إن هذا لساحر﴾؟","answer":"أكدوا بـ﴿إن﴾ واللام لتثبيت التهمة وصرف الأنظار عن المعجزة الواضحة إلى دعوى السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص187–191.","url":""}]},{"id":"s7-632","number":632,"surah":7,"verses":[109],"verseLabel":"الأعراف: 109","question":"لماذا أشاروا إلى موسى بـ﴿هذا﴾ بدل تسميته؟","answer":"اسم الإشارة للحاضر يعيّنه أمامهم، وقد يحمل نبرة تحقير وإبعاد عن وصف الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص187–191.","url":""}]},{"id":"s7-633","number":633,"surah":7,"verses":[109],"verseLabel":"الأعراف: 109","question":"لماذا وصفوه بـ﴿ساحر عليم﴾ لا «ساحر عظيم»؟","answer":"﴿عليم﴾ أي بالغ المعرفة بدقائق السحر، وهو أنسب لتفسير ما شاهدوه ومحاولة مواجهته بسحرة مثله من ﴿عظيم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص187–191.","url":""}]},{"id":"s7-634","number":634,"surah":7,"verses":[109],"verseLabel":"الأعراف: 109","question":"لماذا نُسب القول في الأعراف إلى ﴿الملأ من قوم فرعون﴾، بينما حكاه الشعراء عن فرعون نفسه: ﴿قال لمن حوله﴾؟","answer":"التقدير أن فرعون والملأ قال بعضهم لبعض؛ فحذف فرعون في الأعراف لاشتمال الملأ عليه في المشهد، وصرح الشعراء بقول فرعون لمن حوله.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-635","number":635,"surah":7,"verses":[110],"verseLabel":"الأعراف: 110","question":"لماذا نسب الملأ إلى موسى إرادة إخراجهم: ﴿يريد أن يخرجكم﴾ مع أنه طلب إخراج بني إسرائيل؟","answer":"حوّلوا طلب تحرير بني إسرائيل إلى مؤامرة على الأرض تحريضًا للناس؛ فقلبوا غاية الرسالة السياسية ليحموا سلطانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص192–196.","url":""}]},{"id":"s7-636","number":636,"surah":7,"verses":[110],"verseLabel":"الأعراف: 110","question":"لماذا جاء ﴿يريد﴾ بالمضارع؟","answer":"المضارع يصور الإرادة متجددة قائمة الآن، ويستحضر خطرًا مزعومًا يوشك الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص192–196.","url":""}]},{"id":"s7-637","number":637,"surah":7,"verses":[110],"verseLabel":"الأعراف: 110","question":"ما سرّ تعبيرهم بـ﴿يخرجكم من أرضكم﴾، وإضافة الأرض إليهم؟","answer":"أضافوا الأرض إلى المخاطبين لاستثارة عصبيتهم وخوفهم على الوطن والملك، مع أنهم هم المستبدون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص192–196.","url":""}]},{"id":"s7-638","number":638,"surah":7,"verses":[110],"verseLabel":"الأعراف: 110","question":"لماذا حُذف ذكر السحر من قوله: ﴿يريد أن يخرجكم﴾ مع أنه أساس تهمتهم؟","answer":"حذف ﴿بسحره﴾ لدلالة وصفهم السابق ﴿ساحر عليم﴾ عليه، فاستغنى السياق عن التكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص192–196.","url":""}]},{"id":"s7-639","number":639,"surah":7,"verses":[110],"verseLabel":"الأعراف: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿فماذا تأمرون﴾، وفيه ظهور فرعون مستشيرًا للملأ أو مخاطبًا لهم؟","answer":"إما أن فرعون قال للملأ ﴿فماذا تأمرون﴾ طالبًا رأيهم، أو أن الملأ قالوا لفرعون فحكي الخطاب؛ وفيه اضطراب الطاغية أمام الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص192–196.","url":""}]},{"id":"s7-640","number":640,"surah":7,"verses":[110],"verseLabel":"الأعراف: 110","question":"لماذا اختير فعل ﴿تأمرون﴾ لا «تشيرون»؟","answer":"استعملوا ﴿تأمرون﴾ لا «تشيرون» لأن مشورتهم صارت مما يُعمل به كالأمر، أو لأن فرعون فوّض إليهم تقرير الإجراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص192–196.","url":""}]},{"id":"s7-641","number":641,"surah":7,"verses":[110],"verseLabel":"الأعراف: 110","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿يريد أن يخرجكم من أرضكم﴾، وزاد في الشعراء: ﴿بسحره﴾؟","answer":"اقتصر الأعراف على ﴿يريد أن يخرجكم من أرضكم﴾ لأن لفظ ﴿ساحر﴾ السابق يدل على السحر، وزاد الشعراء ﴿بسحره﴾ في سياق التفصيل.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-642","number":642,"surah":7,"verses":[111],"verseLabel":"الأعراف: 111","question":"ما سرّ تعبيرهم بـ﴿أرجه وأخاه﴾، وما دلالة ﴿أرجه﴾؟","answer":"﴿أرجه﴾ أي أخّره وأمهله ولا تعاجله بالعقوبة؛ حتى يجمع السحرة لمعارضته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص197–203.","url":""}]},{"id":"s7-643","number":643,"surah":7,"verses":[111],"verseLabel":"الأعراف: 111","question":"لماذا جمعوا موسى وأخاه في التأخير مع أن المواجهة صدرت من موسى؟","answer":"أدخلوا هارون معه لأنه شريكه في الرسالة والعون، وإن كان موسى المتصدر لإظهار الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص197–203.","url":""}]},{"id":"s7-644","number":644,"surah":7,"verses":[111],"verseLabel":"الأعراف: 111","question":"لماذا لم يصرح باسم هارون فقال: ﴿وأخاه﴾؟","answer":"اكتفى بوصف الأخوة لأن هارون معروف من سياق القصة، ولإبراز اتحاده بموسى وقربه منه في المهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص197–203.","url":""}]},{"id":"s7-645","number":645,"surah":7,"verses":[111],"verseLabel":"الأعراف: 111","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿وأرسل في المدائن حاشرين﴾، وفي الشعراء: ﴿وابعث في المدائن حاشرين﴾؟","answer":"الإرسال يتضمن البعث مع معنى صدوره من صاحب سلطان، فناسب في الأعراف إظهار أن المخاطب فرعون؛ والشعراء عبرت بالبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص197–203.","url":""}]},{"id":"s7-646","number":646,"surah":7,"verses":[111],"verseLabel":"الأعراف: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿في المدائن﴾ لا «إلى المدائن»؟","answer":"﴿في المدائن﴾ تصور الحاشرين منتشرين داخلها يجوبونها ويبحثون، لا متجهين إلى حدودها فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص197–203.","url":""}]},{"id":"s7-647","number":647,"surah":7,"verses":[111],"verseLabel":"الأعراف: 111","question":"لماذا جمع ﴿المدائن﴾؟","answer":"الجمع لأن السحرة موزعون في مدن متعددة، فأرادوا استقصاء مراكزهم كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص197–203.","url":""}]},{"id":"s7-648","number":648,"surah":7,"verses":[111],"verseLabel":"الأعراف: 111","question":"لماذا وصف المرسلين بـ﴿حاشرين﴾ لا «جامعين»؟","answer":"الحشر جمع الناس من جهات مختلفة وسوقهم إلى مكان واحد، وهو أدق من مجرد الجمع في تصوير مهمتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص197–203.","url":""}]},{"id":"s7-649","number":649,"surah":7,"verses":[112],"verseLabel":"الأعراف: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿يأتوك﴾ فجعل السحرة يأتون فرعون لا موسى؟","answer":"جعل الإتيان إلى فرعون لأنه صاحب الأمر الذي طلب جمعهم، والمبارزة بموسى تقع بعد حضورهم عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص204–207.","url":""}]},{"id":"s7-650","number":650,"surah":7,"verses":[112],"verseLabel":"الأعراف: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿بكل ساحر﴾، وما الذي أفادته ﴿كل﴾؟","answer":"﴿كل﴾ تفيد الاستقصاء العرفي أو الكثرة؛ أي لا تتركوا ساحرًا متقنًا يمكن الاستعانة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص204–207.","url":""}]},{"id":"s7-651","number":651,"surah":7,"verses":[112],"verseLabel":"الأعراف: 112","question":"لماذا قرئ ﴿ساحر عليم﴾ و﴿سحّار عليم﴾؟","answer":"﴿ساحر﴾ اسم فاعل، و﴿سحّار﴾ صيغة مبالغة في كثرة السحر وإتقانه؛ وكلتا القراءتين تؤكد طلب أمهرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص204–207.","url":""}]},{"id":"s7-652","number":652,"surah":7,"verses":[112],"verseLabel":"الأعراف: 112","question":"لماذا وصف كل ساحر بـ﴿عليم﴾؟","answer":"﴿عليم﴾ يدل على رسوخ معرفته بصناعة السحر ودقائقه، لا مجرد ممارسته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص204–207.","url":""}]},{"id":"s7-653","number":653,"surah":7,"verses":[112],"verseLabel":"الأعراف: 112","question":"لماذا لم يقولوا: يأتوك بسحرة كثيرين؟","answer":"التعبير بـ﴿كل ساحر عليم﴾ أوجز وأقوى في طلب استقصاء كل فرد متصف بالخبرة من قول «سحرة كثيرين».","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص204–207.","url":""}]},{"id":"s7-654","number":654,"surah":7,"verses":[112],"verseLabel":"الأعراف: 112","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿بكل ساحر عليم﴾، وفي الشعراء: ﴿بكل سحّار عليم﴾ بصيغة المبالغة؟","answer":"جاء ﴿ساحر﴾ في الأعراف موافقةً لما قبله ﴿إن هذا لساحر عليم﴾، وجاء ﴿سحّار﴾ في الشعراء على صيغة المبالغة التي اختص بها سياقها.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-655","number":655,"surah":7,"verses":[79],"verseLabel":"الأعراف: 112؛ يونس: 79","question":"ما سرّ اختلاف جهة الأمر: ﴿يأتوك بكل ساحر عليم﴾ على لسان الملأ في الأعراف، و﴿ائتوني بكل ساحر عليم﴾ على لسان فرعون في يونس؟","answer":"في الأعراف الحكاية عن مشورة الملأ: أرسل حاشرين يأتوك بالسحرة؛ وفي يونس أصدر فرعون الأمر بنفسه ﴿ائتوني﴾، فناسب كل فعل جهة الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص28–33.","url":""}]},{"id":"s7-656","number":656,"surah":7,"verses":[113],"verseLabel":"الأعراف: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاء السحرة فرعون﴾، دون أن يقال: إلى فرعون؟","answer":"عُدّي ﴿جاء﴾ بنفسه إلى فرعون على معنى قصدوه وحضروه، وفي حذف ﴿إلى﴾ سرعة وصولهم واتصالهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص208–214.","url":""}]},{"id":"s7-657","number":657,"surah":7,"verses":[113],"verseLabel":"الأعراف: 113","question":"ما سرّ تقديم مجيء السحرة قبل حوارهم؟","answer":"قدم مجيئهم لإقامة المشهد وبيان تنفيذ خطة الحشر، ثم نقل الحوار الذي كشف غايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص208–214.","url":""}]},{"id":"s7-658","number":658,"surah":7,"verses":[113],"verseLabel":"الأعراف: 113","question":"لماذا بدأ السحرة بالسؤال عن الأجر قبل المبارزة؟","answer":"كشف سؤالهم أن باعثهم الأجر والمنزلة لا طلب الحق؛ فجعلوا المقابل شرطًا لبذل مهارتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص208–214.","url":""}]},{"id":"s7-659","number":659,"surah":7,"verses":[113],"verseLabel":"الأعراف: 113","question":"ما سرّ تعبيرهم بـ﴿إن لنا لأجرًا﴾ بتوكيدين؟","answer":"أكدوا بـ﴿إن﴾ واللام لأنهم أرادوا ضمان الأجر وتثبيته قبل العمل، لا مجرد الاستفهام عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص208–214.","url":""}]},{"id":"s7-660","number":660,"surah":7,"verses":[113],"verseLabel":"الأعراف: 113","question":"لماذا نكّروا ﴿أجرًا﴾؟","answer":"نكروه للتعظيم والتكثير؛ أي أجرًا عظيمًا مجزيًا يليق بما سيصنعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص208–214.","url":""}]},{"id":"s7-661","number":661,"surah":7,"verses":[113],"verseLabel":"الأعراف: 113","question":"ما سرّ تعبيرهم بـ﴿إن كنا نحن الغالبين﴾ وإظهار ضمير ﴿نحن﴾؟","answer":"أظهروا ﴿نحن﴾ توكيدًا لاختصاصهم بالغلبة واستعلاءً بثقتهم في صناعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص208–214.","url":""}]},{"id":"s7-662","number":662,"surah":7,"verses":[113],"verseLabel":"الأعراف: 113","question":"لماذا جاء في الشعراء استفهام صريح: ﴿أئن لنا لأجرًا﴾، وهنا ﴿إن لنا لأجرًا﴾؟","answer":"يجوز أن تكون همزة الاستفهام مقدرة في الأعراف، فالمعنى سؤال في الموضعين؛ وصرح بها في الشعراء، وحذفها هنا لدلالة المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص208–214.","url":""}]},{"id":"s7-663","number":663,"surah":7,"verses":[113],"verseLabel":"الأعراف: 113","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وجاء السحرة فرعون قالوا﴾، وفي الشعراء: ﴿فلما جاء السحرة قالوا لفرعون﴾؟","answer":"في الأعراف أضمر ﴿فلما﴾ اختصارًا، فكأنه: فلما جاء السحرة فرعون قالوا؛ وفي الشعراء صرح بها، وأظهر فرعون في الموضع الأول وأضمره في الثاني.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-664","number":664,"surah":7,"verses":[114],"verseLabel":"الأعراف: 114","question":"لماذا أجاب فرعون بكلمة واحدة: ﴿نعم﴾؟","answer":"أجاب بـ﴿نعم﴾ فورًا تحقيقًا لمطلبهم وإظهارًا لثقته بحاجته إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص215–218.","url":""}]},{"id":"s7-665","number":665,"surah":7,"verses":[114],"verseLabel":"الأعراف: 114","question":"لماذا لم يكتف بالأجر بل قال: ﴿وإنكم لمن المقربين﴾؟","answer":"زادهم وعد القرب من مجلسه وسلطانه فوق المال، ليبلغ تحريضهم غايته ويضمن ولاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص215–218.","url":""}]},{"id":"s7-666","number":666,"surah":7,"verses":[114],"verseLabel":"الأعراف: 114","question":"لماذا أكد التقريب بـ﴿إن﴾ واللام و﴿من﴾؟","answer":"تتابع ﴿إن﴾ واللام و﴿من﴾ لتوكيد الوعد وإدخالهم يقينًا في زمرة خاصته المقربين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص215–218.","url":""}]},{"id":"s7-667","number":667,"surah":7,"verses":[114],"verseLabel":"الأعراف: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿من المقربين﴾ لا «مقربون»؟","answer":"﴿من المقربين﴾ تدخلهم في طبقة معروفة ذات منزلة، وهو أبلغ من مجرد إثبات أنهم مقربون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص215–218.","url":""}]},{"id":"s7-668","number":668,"surah":7,"verses":[114],"verseLabel":"الأعراف: 114","question":"ما المقابلة بين طلبهم ﴿أجرًا﴾ ووعده لهم بالقرب؟","answer":"طلبوا منفعة المال، فوعدهم معها منفعة الجاه والقرب؛ فصعد بالجزاء ليشتد تنافسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص215–218.","url":""}]},{"id":"s7-669","number":669,"surah":7,"verses":[114],"verseLabel":"الأعراف: 114","question":"ما سرّ زيادة ﴿إذًا﴾ في قول فرعون في الشعراء: ﴿نعم وإنكم إذًا لمن المقربين﴾، وحذفها في الأعراف؟","answer":"﴿إذًا﴾ في الشعراء تصرح بالجزاء: إن غلبتم قربتكم؛ وهي مقدرة في الأعراف وحذفت اختصارًا.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-670","number":670,"surah":7,"verses":[115],"verseLabel":"الأعراف: 115","question":"لماذا خيّر السحرة موسى: ﴿إما أن تلقي وإما أن نكون نحن الملقين﴾؟","answer":"التخيير إظهار للثقة والأدب الظاهر قبل المنافسة، مع ما فيه من تحدٍ لمن يبدأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص219–224.","url":""}]},{"id":"s7-671","number":671,"surah":7,"verses":[115],"verseLabel":"الأعراف: 115","question":"ما سرّ التعبير أولًا بـ﴿أن تلقي﴾ بالفعل، وثانيًا بـ﴿أن نكون نحن الملقين﴾ بالكون والاسم؟","answer":"قالوا لموسى ﴿أن تلقي﴾ بالفعل المجرد، ووصفوا أنفسهم بالاسم ﴿الملقين﴾ مع ﴿نحن﴾ لتوكيد ثبات الإلقاء واختصاصهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص219–224.","url":""}]},{"id":"s7-672","number":672,"surah":7,"verses":[115],"verseLabel":"الأعراف: 115","question":"لماذا كرروا ﴿إما﴾ في طرفي التخيير؟","answer":"تكرار ﴿إما﴾ يسوي طرفي التخيير ويوضحهما، فلا يلتبس المعطوف بأنه تابع للأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص219–224.","url":""}]},{"id":"s7-673","number":673,"surah":7,"verses":[115],"verseLabel":"الأعراف: 115","question":"لماذا أظهروا ضمير ﴿نحن﴾؟","answer":"ضمير ﴿نحن﴾ لتوكيد أنهم الفريق المقابل وتضخيم شأنهم واستعدادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص219–224.","url":""}]},{"id":"s7-674","number":674,"surah":7,"verses":[115],"verseLabel":"الأعراف: 115","question":"لماذا سمّى فعلهم إلقاءً قبل بيان ما ألقوه؟","answer":"سماه إلقاءً إجمالًا وتشويقًا قبل أن يكشف ما ألقوه من الحبال والعصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص219–224.","url":""}]},{"id":"s7-675","number":675,"surah":7,"verses":[115],"verseLabel":"الأعراف: 115","question":"ما سرّ اختلاف التعبير بين قول السحرة في الأعراف: ﴿وإما أن نكون نحن الملقين﴾، وفي طه: ﴿وإما أن نكون أول من ألقى﴾؟","answer":"جاءت صيغة الأعراف موافقةً لفاصلتها ﴿الملقين﴾، وجاء في طه ﴿أول من ألقى﴾ بما يلائم فواصل سياقها؛ والمعنى في كليهما طلب البدء.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-676","number":676,"surah":7,"verses":[116],"verseLabel":"الأعراف: 116","question":"لماذا أجاب موسى باقتضاب: ﴿ألقوا﴾؟","answer":"اقتضب ثقةً بربه وعدم مبالاة بسحرهم؛ فأمرهم أن يظهروا أقصى ما عندهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص225–229.","url":""}]},{"id":"s7-677","number":677,"surah":7,"verses":[116],"verseLabel":"الأعراف: 116","question":"لماذا سمح لهم موسى أن يبدؤوا بالإلقاء؟","answer":"سمح لهم بالبدء ليظهر باطلهم كاملًا أمام الناس، ثم تأتي المعجزة فتبطل ما صنعوا فلا تُتهم بالمبادأة أو الخداع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص225–229.","url":""}]},{"id":"s7-678","number":678,"surah":7,"verses":[116],"verseLabel":"الأعراف: 116","question":"لماذا كرر فعل الإلقاء: ﴿قال ألقوا فلما ألقوا﴾؟","answer":"التكرار يطابق الأمرَ وقوعُه ويصور سرعة التنفيذ: أمرهم بالإلقاء فألقوا فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص225–229.","url":""}]},{"id":"s7-679","number":679,"surah":7,"verses":[116],"verseLabel":"الأعراف: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿سحروا أعين الناس﴾، دون أن يقال: سحروا الناس؟","answer":"قصر أثر سحرهم على الأعين لأنه تخييل بصري، لا تغيير لحقيقة الحبال والعصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص225–229.","url":""}]},{"id":"s7-680","number":680,"surah":7,"verses":[116],"verseLabel":"الأعراف: 116","question":"لماذا قدّم سحر الأعين على إرهاب الناس؟","answer":"بدأ بسبب الرهبة وهو خداع الأبصار، ثم ذكر أثره النفسي في الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص225–229.","url":""}]},{"id":"s7-681","number":681,"surah":7,"verses":[116],"verseLabel":"الأعراف: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿واسترهبوهم﴾ لا «وأرهبوهم»؟","answer":"الاسترهـاب طلب الرهبة واستجلابها والمبالغة في إحداثها، فهو أقوى من مجرد أرهبوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص225–229.","url":""}]},{"id":"s7-682","number":682,"surah":7,"verses":[116],"verseLabel":"الأعراف: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاءوا بسحر عظيم﴾ بعد تفصيل أثره؟","answer":"بعد ذكر أثره في العين والنفس أجمل حقيقته ووصف ضخامته؛ فالتفصيل شاهد على الحكم بأنه سحر عظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص225–229.","url":""}]},{"id":"s7-683","number":683,"surah":7,"verses":[116],"verseLabel":"الأعراف: 116","question":"لماذا وصف السحر بـ﴿عظيم﴾ مع أنه باطل؟","answer":"وصف بالعظم من جهة قوته في التخييل وأثره في الناس وكثرة وسائله، لا من جهة الحق والقيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص225–229.","url":""}]},{"id":"s7-684","number":684,"surah":7,"verses":[117],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿وأوحينا إلى موسى﴾ في أثناء المواجهة؟","answer":"ذكر الوحي في قلب المواجهة يبين أن حركة موسى بتوجيه ربه، وأن المعجزة ليست صناعة بشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص230–237.","url":""}]},{"id":"s7-685","number":685,"surah":7,"verses":[117],"verseLabel":"الأعراف: 117","question":"لماذا لم يقل لموسى هنا: ألق، بل حكى الوحي إليه؟","answer":"حكى الوحي ليبرز مصدر الأمر الإلهي وتأييد موسى، بدل أن يسرد فعلًا معزولًا عن مصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص230–237.","url":""}]},{"id":"s7-686","number":686,"surah":7,"verses":[117],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿أن ألق عصاك﴾، فعاد إلى العصا المضافة إليه؟","answer":"إضافة العصا تذكر بأنها أداته المعهودة نفسها، وأن التحول من الشيء المألوف هو موضع الإعجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص230–237.","url":""}]},{"id":"s7-687","number":687,"surah":7,"verses":[117],"verseLabel":"الأعراف: 117","question":"لماذا جاءت المفاجأة مرة أخرى: ﴿فإذا هي تلقف﴾؟","answer":"﴿إذا﴾ الفجائية تصور شروع العصا في ابتلاع إفكهم فور إلقائها، فتحول المشهد في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص230–237.","url":""}]},{"id":"s7-688","number":688,"surah":7,"verses":[117],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿تلقف﴾ بالمضارع لا «لقفت»؟","answer":"المضارع يستحضر سرعة الالتقاط وتتابعه أمام العيون، كأن القارئ يشاهدها تبتلع ما ألقوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص230–237.","url":""}]},{"id":"s7-689","number":689,"surah":7,"verses":[117],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿تلقف ما يأفكون﴾، وفي طه: ﴿تلقف ما صنعوا﴾؟","answer":"﴿ما يأفكون﴾ يكشف حقيقة سحرهم الأخلاقية: كذب مصروف عن الحق، و﴿ما صنعوا﴾ يركز في طه على إحكام عملهم الذي أبطلته العصا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص230–237.","url":""}]},{"id":"s7-690","number":690,"surah":7,"verses":[117],"verseLabel":"الأعراف: 117","question":"لماذا عبّر عن سحرهم بـ﴿ما يأفكون﴾؟","answer":"الإفك قلب الحقيقة وصرفها؛ فسحرهم أظهر الساكن متحركًا، ولذلك سمى عملهم إفكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص230–237.","url":""}]},{"id":"s7-691","number":691,"surah":7,"verses":[118],"verseLabel":"الأعراف: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿فوقع الحق﴾، وما معنى وقوع الحق؟","answer":"الوقوع هنا الثبوت والظهور والتحقق؛ فلما بطلت المخايل استقر الحق ظاهرًا لا يدفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص238–243.","url":""}]},{"id":"s7-692","number":692,"surah":7,"verses":[118],"verseLabel":"الأعراف: 118","question":"لماذا عُرّف ﴿الحق﴾؟","answer":"عُرّف لأنه الحق المعهود الذي جاء به موسى من الله، وللدلالة على كماله في مقابل الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص238–243.","url":""}]},{"id":"s7-693","number":693,"surah":7,"verses":[118],"verseLabel":"الأعراف: 118","question":"لماذا قابل وقوع الحق بـ﴿وبطل ما كانوا يعملون﴾؟","answer":"قابل ثبوت الحق بزوال عملهم؛ فظهور أحد الضدين يقتضي بطلان الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص238–243.","url":""}]},{"id":"s7-694","number":694,"surah":7,"verses":[118],"verseLabel":"الأعراف: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كانوا يعملون﴾ لا «ما عملوا»؟","answer":"﴿كانوا يعملون﴾ تدل على استمرار صناعتهم واعتيادهم السحر، فالباطل شمل مهنتهم المتكررة لا حركة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص238–243.","url":""}]},{"id":"s7-695","number":695,"surah":7,"verses":[118],"verseLabel":"الأعراف: 118","question":"لماذا سمّى السحر ﴿عملًا﴾ هنا، و﴿صنعوا﴾ في طه، و﴿يأفكون﴾ في الأعراف قبلها؟","answer":"﴿يأفكون﴾ يذم كذبه وقلبه للحقائق، و﴿صنعوا﴾ يبرز إحكام الحيلة، و﴿يعملون﴾ يعم نشاطهم المتكرر؛ وكل لفظ يلائم زاوية السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص238–243.","url":""}]},{"id":"s7-696","number":696,"surah":7,"verses":[119],"verseLabel":"الأعراف: 119","question":"لماذا بُني ﴿فغُلبوا﴾ للمجهول؟","answer":"بني للمجهول لتركيز النظر على وقوع الهزيمة الساحقة بهم، ولأن الغالب الحقيقي معلوم من ظهور آية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص244–248.","url":""}]},{"id":"s7-697","number":697,"surah":7,"verses":[119],"verseLabel":"الأعراف: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿هنالك﴾ باسم الإشارة للمكان البعيد؟","answer":"﴿هنالك﴾ تشير إلى مقام المواجهة الحاسم وتبعده رتبةً لعظم ما وقع فيه، لا لمجرد البعد المكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص244–248.","url":""}]},{"id":"s7-698","number":698,"surah":7,"verses":[119],"verseLabel":"الأعراف: 119","question":"لماذا عطف ﴿وانقلبوا﴾ على ﴿غلبوا﴾؟","answer":"العطف يبين نتيجتين متعاقبتين: وقعت عليهم الغلبة في الميدان، ثم عادوا من حال العزة والطمع إلى الذلة والصغار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص244–248.","url":""}]},{"id":"s7-699","number":699,"surah":7,"verses":[119],"verseLabel":"الأعراف: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿انقلبوا صاغرين﴾ لا «رجعوا مهزومين»؟","answer":"الانقلاب رجوع تتحول معه الحال؛ فقد جاؤوا يطلبون الغلبة والأجر ثم عادوا أذلاء، و﴿صاغرين﴾ تصور هزيمةً أصابت مكانتهم لا مجرد خسارة الميدان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص244–248.","url":""}]},{"id":"s7-700","number":700,"surah":7,"verses":[119],"verseLabel":"الأعراف: 119","question":"لماذا وصفوا بـ﴿صاغرين﴾؟","answer":"الصغار ذلة مع قهر؛ فناسب من تكبروا بالسحر ثم أظهر الله عجزهم أمام الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص244–248.","url":""}]},{"id":"s7-701","number":701,"surah":7,"verses":[120],"verseLabel":"الأعراف: 120","question":"لماذا بُني ﴿وألقي السحرة ساجدين﴾ للمجهول؟","answer":"بُني للمجهول لتصوير قوة الحق التي خرّوا أمامها سريعًا، حتى بدا السجود كأنه أُلقي عليهم، مع علم فاعله من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص249–253.","url":""}]},{"id":"s7-702","number":702,"surah":7,"verses":[120],"verseLabel":"الأعراف: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿أُلقي السحرة﴾ مع أنهم سجدوا باختيارهم؟","answer":"مع اختيارهم الإيمان، كانت المعجزة من شدة ظهورها سببًا غالبًا حملهم على السجود بلا تردد؛ فصوّر الفعل الاختياري في هيئة إلقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص249–253.","url":""}]},{"id":"s7-703","number":703,"surah":7,"verses":[120],"verseLabel":"الأعراف: 120","question":"ما سرّ تقديم وصفهم ﴿السحرة﴾ مع أنهم صاروا مؤمنين؟","answer":"أبقى وصف ﴿السحرة﴾ ليظهر أن أهل الصنعة أنفسهم عرفوا الفرق بين السحر والمعجزة؛ فشهادتهم أقوى حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص249–253.","url":""}]},{"id":"s7-704","number":704,"surah":7,"verses":[120],"verseLabel":"الأعراف: 120","question":"لماذا عبّر بـ﴿ساجدين﴾ لا «فسجدوا»؟","answer":"﴿ساجدين﴾ حال تصور هيئة سقوطهم وثباتهم في السجود لحظة الإلقاء، بخلاف فعل مجرد يخبر بوقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص249–253.","url":""}]},{"id":"s7-705","number":705,"surah":7,"verses":[120],"verseLabel":"الأعراف: 120","question":"ما مناسبة انتقالهم من الإلقاء للسحر إلى أن يُلقوا هم ساجدين؟","answer":"قابل إلقاءهم الحبال والعصي بالباطل بإلقائهم هم ساجدين للحق؛ فانقلب الفاعل في السحر واقعًا تحت سلطان المعجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص249–253.","url":""}]},{"id":"s7-706","number":706,"surah":7,"verses":[46],"verseLabel":"الأعراف: 120؛ طه: 70؛ الشعراء: 46","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وألقي السحرة ساجدين﴾ بالواو، وفي طه والشعراء: ﴿فألقي السحرة﴾ بالفاء؟","answer":"عُطف السجود بالواو في الأعراف بعد سلسلة نتائج متعاقبة بالفاء اكتمل بها مشهد الغلبة، وجاءت الفاء في طه والشعراء لإبرازه نتيجة فورية لمعاينة المعجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص545–546، تحت الشعراء: 46.","url":""}]},{"id":"s7-707","number":707,"surah":7,"verses":[121],"verseLabel":"الأعراف: 121","question":"ما سرّ مبادرة السحرة بقولهم: ﴿آمنا برب العالمين﴾ دون مقدمة؟","answer":"بادروا بالإيمان بلا استئذان ولا تمهيد لأن معرفتهم بالسحر أورثتهم يقينًا فوريًا بأن ما رأوه آية ربانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص254–257.","url":""}]},{"id":"s7-708","number":708,"surah":7,"verses":[121],"verseLabel":"الأعراف: 121","question":"لماذا اختاروا وصف ﴿رب العالمين﴾ نفسه الذي واجه به موسى فرعون؟","answer":"اختاروا ﴿رب العالمين﴾ ردًا على ربوبية فرعون المزعومة، وموافقةً لما أعلن موسى أنه رسول منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص254–257.","url":""}]},{"id":"s7-709","number":709,"surah":7,"verses":[121],"verseLabel":"الأعراف: 121","question":"ما سرّ تعبير السحرة بصيغة الجمع في قولهم: ﴿آمنا﴾؟","answer":"صيغة الجمع تعلن اتفاقهم جميعًا على الإيمان، فتقوي الشهادة وتبطل دعوى أن ما وقع انفعال فرد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص254–257.","url":""}]},{"id":"s7-710","number":710,"surah":7,"verses":[121],"verseLabel":"الأعراف: 121","question":"لماذا لم يقولوا: آمنا بموسى؟","answer":"توجهوا إلى رب موسى لا إلى شخص موسى؛ فالإيمان عبادة لله وتصديق لآياته، لا تعلق بالبشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص254–257.","url":""}]},{"id":"s7-711","number":711,"surah":7,"verses":[122],"verseLabel":"الأعراف: 122","question":"لماذا بيّنوا بعد ذلك: ﴿رب موسى وهارون﴾؟","answer":"بيّنوا ﴿رب موسى وهارون﴾ ليرفعوا احتمال أن يريد فرعون برب العالمين نفسه أو معبودًا آخر، فعيّنوا رب الرسولين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص258–261.","url":""}]},{"id":"s7-712","number":712,"surah":7,"verses":[122],"verseLabel":"الأعراف: 122","question":"ما سرّ تقديم موسى على هارون؟","answer":"قُدم موسى لأنه صاحب المواجهة وإظهار العصا والمتصدر في الرسالة، وهارون تابع له في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص258–261.","url":""}]},{"id":"s7-713","number":713,"surah":7,"verses":[122],"verseLabel":"الأعراف: 122","question":"لماذا أضافوا الرب إلى موسى وهارون مع أنه رب العالمين؟","answer":"الإضافة تعيّن رب العالمين الذي دعوا إليه وتعلن انضمامهم إلى دعوة موسى وهارون في وجه فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص258–261.","url":""}]},{"id":"s7-714","number":714,"surah":7,"verses":[122],"verseLabel":"الأعراف: 122","question":"لماذا جاءت ﴿رب موسى وهارون﴾ آية مستقلة قصيرة؟","answer":"استقلالها وقصرها يمنحان التعيين قوةً وحسمًا، ويجعلان اسمَي الرسولين إعلانًا عقديًا بارزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص258–261.","url":""}]},{"id":"s7-715","number":715,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"ما سرّ تعبير فرعون بـ﴿آمنتم به قبل أن آذن لكم﴾، فجعل الإيمان محتاجًا إلى إذنه؟","answer":"كشف قوله أن الطاغية يعد ضمائر الناس ملكًا له، فلا يجيز الإيمان إلا بإذنه؛ وفي ذلك تصوير لأقصى الاستبداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-716","number":716,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"لماذا جاء الاستفهام في قراءة ﴿أآمنتم﴾ للإنكار؟","answer":"الاستفهام إنكاري توبيخي؛ يستنكر استقلالهم بالإيمان ويهددهم، لا يستفهم عن وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-717","number":717,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿آمنتم به﴾، وفي طه والشعراء: ﴿آمنتم له﴾؟","answer":"﴿آمنتم به﴾ تفيد التصديق بموسى أو بالله، و﴿آمنتم له﴾ تتضمن معنى الانقياد والتصديق لما دعا إليه؛ وكل سياق يبرز جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-718","number":718,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"لماذا قدّم ﴿به﴾ على ﴿قبل أن آذن لكم﴾؟","answer":"قدم المتعلق ﴿به﴾ للعناية بموضع غضبه: الإيمان بمن جعله خصمًا، قبل اعتراضه على سبق الإذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-719","number":719,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"لماذا عبّر بـ﴿قبل أن آذن لكم﴾ لا «بغير إذني»؟","answer":"﴿قبل أن آذن﴾ يصور سباقهم المزعوم لإرادته وتجاوزهم زمن سلطانه، وهو أشد إبرازًا لاستبداده من ﴿بغير إذني﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-720","number":720,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"لماذا انتقل فورًا إلى اتهامهم: ﴿إن هذا لمكر مكرتموه﴾؟","answer":"لما عجز عن إنكار المعجزة اخترع تفسير المؤامرة ليحفظ سلطانه ويصرف الناس عن دلالة الإيمان الجماعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-721","number":721,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"لماذا كرر مادة المكر: ﴿لمكر مكرتموه﴾؟","answer":"الجمع بين الاسم والفعل توكيد؛ سمى الحادث كله مكرًا ثم نسب صنعه إليهم عمدًا، تثبيتًا لتهمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-722","number":722,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿في المدينة﴾ مع أن المكر المزعوم ظهر في ساحة اللقاء؟","answer":"زعم أن الاتفاق دُبر داخل المدينة قبل اللقاء، ليصور الإيمان مؤامرة قديمة لا استجابةً للآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-723","number":723,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿لتخرجوا منها أهلها﴾ فردّ عليهم التهمة نفسها التي اتهموا بها موسى؟","answer":"رد عليهم تهمة الإخراج التي نسبوها إلى موسى، فاتهم موسى والسحرة بأن غايتهم إخراج أهل المدينة؛ وهو قلب للحقيقة وتحريض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-724","number":724,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"لماذا قدّم الجار والمجرور في ﴿منها أهلها﴾؟","answer":"قدم ﴿منها﴾ لأن الإخراج من المدينة هو موضع التخويف والعناية، ثم ذكر أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-725","number":725,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"لماذا هددهم بإبهام: ﴿فسوف تعلمون﴾ قبل تفصيل العقوبة؟","answer":"أبهم ما سيعلمونه ليضخم الوعيد ويفتح الخيال على عقاب مهول، ثم فصله في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص262–268.","url":""}]},{"id":"s7-726","number":726,"surah":7,"verses":[123],"verseLabel":"الأعراف: 123","question":"ما سرّ التصريح باسم فرعون في الأعراف: ﴿قال فرعون آمنتم به﴾، وإضماره في طه والشعراء؟","answer":"صُرّح باسم فرعون في الأعراف لبعد ذكره بآيات، وأضمر في طه والشعراء لقرب ذكره؛ فالإظهار يرفع اللبس.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-727","number":727,"surah":7,"verses":[124],"verseLabel":"الأعراف: 124","question":"لماذا أكد الوعيد باللام والنون: ﴿لأقطعن... ولأصلبنكم﴾؟","answer":"اللام ونون التوكيد الثقيلة تصوران قسمه وتصميمه على تنفيذ التعذيب، في مواجهة ثبات المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص269–273.","url":""}]},{"id":"s7-728","number":728,"surah":7,"verses":[124],"verseLabel":"الأعراف: 124","question":"لماذا قدّم تقطيع الأيدي والأرجل على الصلب؟","answer":"قدم القطع لأنه تعذيب وتمثيل يسبق القتل بالصلب، وليطيل عليهم الألم قبل النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص269–273.","url":""}]},{"id":"s7-729","number":729,"surah":7,"verses":[124],"verseLabel":"الأعراف: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿أيديكم وأرجلكم﴾ فجمع الطرفين؟","answer":"جمع الأيدي والأرجل لاستيعاب السحرة وبيان أن العقوبة ستصيب طرفي كل واحد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص269–273.","url":""}]},{"id":"s7-730","number":730,"surah":7,"verses":[124],"verseLabel":"الأعراف: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿من خلاف﴾؟","answer":"أي يقطع اليد من جانب والرجل من الجانب المقابل؛ فتشتد الإعاقة والتشويه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص269–273.","url":""}]},{"id":"s7-731","number":731,"surah":7,"verses":[124],"verseLabel":"الأعراف: 124","question":"لماذا عطف الصلب بـ﴿ثم﴾؟","answer":"﴿ثم﴾ للترتيب مع التراخي، فالتقطيع مرحلة يعقبها الصلب، وفيها تهويل بطول العذاب وتعدد أطواره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص269–273.","url":""}]},{"id":"s7-732","number":732,"surah":7,"verses":[124],"verseLabel":"الأعراف: 124","question":"لماذا ختم التهديد بـ﴿أجمعين﴾؟","answer":"﴿أجمعين﴾ تهديد بالاستئصال الشامل؛ لا يستثني من المؤمنين أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص269–273.","url":""}]},{"id":"s7-733","number":733,"surah":7,"verses":[124],"verseLabel":"الأعراف: 124","question":"ما سرّ مجيء ﴿ثم لأصلبنكم﴾ في الأعراف، و﴿ولأصلبنكم﴾ في طه والشعراء؟","answer":"جاءت ﴿ثم﴾ في الأعراف لتصوير مرحلتي التعذيب وترتيبهما، وراعت طه والشعراء العطف بالواو مع نسق فواصلهما واختصارهما.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-734","number":734,"surah":7,"verses":[125],"verseLabel":"الأعراف: 125","question":"لماذا أجاب السحرة التهديد بقولهم: ﴿إنا إلى ربنا منقلبون﴾؟","answer":"واجهوا تهديده بأن الموت ليس نهاية بل رجوع إلى ربهم؛ فسلطان فرعون ينتهي عند الجسد وحكم الله هو الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص274–278.","url":""}]},{"id":"s7-735","number":735,"surah":7,"verses":[125],"verseLabel":"الأعراف: 125","question":"لماذا أكدوا قولهم بـ﴿إن﴾؟","answer":"أكدوا بـ﴿إن﴾ ثبات يقينهم بالرجوع إلى الله في مقابل وعيده المؤكد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص274–278.","url":""}]},{"id":"s7-736","number":736,"surah":7,"verses":[125],"verseLabel":"الأعراف: 125","question":"لماذا قدّموا ﴿إلى ربنا﴾ على ﴿منقلبون﴾؟","answer":"قدموا ﴿إلى ربنا﴾ للاختصاص والعناية: إلى ربنا وحده المصير، لا إلى سلطانك وحكمك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص274–278.","url":""}]},{"id":"s7-737","number":737,"surah":7,"verses":[125],"verseLabel":"الأعراف: 125","question":"ما سرّ تعبير السحرة بـ﴿ربنا﴾ في وجه فرعون؟","answer":"إضافة الرب إليهم إعلان ولائهم لله وقطع لربوبية فرعون عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص274–278.","url":""}]},{"id":"s7-738","number":738,"surah":7,"verses":[125],"verseLabel":"الأعراف: 125","question":"لماذا اختاروا ﴿منقلبون﴾ لا «راجعون» أو «ميتون»؟","answer":"الانقلاب رجوع مع تحول من حال إلى حال؛ فهو انتقال بالموت إلى حكم الله وثوابه، لا فناء مجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص274–278.","url":""}]},{"id":"s7-739","number":739,"surah":7,"verses":[125],"verseLabel":"الأعراف: 125","question":"ما سرّ زيادة ﴿لا ضير﴾ في الشعراء قبل ﴿إنا إلى ربنا منقلبون﴾، وحذفها في الأعراف؟","answer":"زاد الشعراء ﴿لا ضير﴾ لأن قصتها أبسط وأوفى في حوار المواجهة، أما الأعراف فاختصرت فبدأت مباشرة بعلة عدم المبالاة: الرجوع إلى الله.","sources":[{"label":"أسرار التكرار في القرآن: سورة الأعراف.","url":""}]},{"id":"s7-740","number":740,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"ما سرّ تعبيرهم بـ﴿وما تنقم منا﴾، وما دلالة ﴿تنقم﴾؟","answer":"﴿تنقم﴾ أي تعيب وتكره وتعاقب؛ فهم ينكرون أن يكون له عليهم مأخذ إلا إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-741","number":741,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"لماذا جاء القصر: ﴿إلا أن آمنا﴾؟","answer":"القصر يفضح ظلم فرعون: لا جريمة لهم إلا أن صدقوا آيات ربهم حين ظهرت.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-742","number":742,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"ما سرّ تعبيرهم بـ﴿آمنا بآيات ربنا﴾ دون: آمنا بموسى؟","answer":"نسبوا إيمانهم إلى آيات ربهم لأنها سبب اليقين وموضوع التصديق، لا إلى شخص موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-743","number":743,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"لماذا جمعوا ﴿آيات﴾ مع أن المشهد أظهر العصا؟","answer":"جمعوا الآيات لأن العصا واليد وما تضمنه المشهد من دلائل صدق موسى كلها آيات، ولأنهم آمنوا بجنس آيات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-744","number":744,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"ما سرّ تكرار قولهم ﴿ربنا﴾ في خطاب فرعون؟","answer":"كرروا ﴿ربنا﴾ تحديًا لربوبية فرعون وتثبيتًا لانتقال ولائهم إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-745","number":745,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"لماذا قيدوا إيمانهم بـ﴿لما جاءتنا﴾؟","answer":"﴿لما جاءتنا﴾ تبيّن سرعة استجابتهم عند ظهور الدليل، وتنفي تهمة التآمر السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-746","number":746,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"لماذا انتقلوا من محاورة فرعون إلى الدعاء: ﴿ربنا أفرغ علينا صبرًا﴾؟","answer":"بعد أن بان عجز فرعون وتهديده انقطع التعلق به، فتوجهوا إلى من يملك القلوب والمصير طالبين الثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-747","number":747,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"لماذا استعير الإفراغ للصبر: ﴿أفرغ علينا صبرًا﴾؟","answer":"شُبّه الصبر بماء كثير يفرغ عليهم فيغمرهم؛ فطلبوا صبرًا واسعًا يحيط بنفوسهم أمام العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-748","number":748,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"لماذا عُدّي الإفراغ بـ﴿على﴾؟","answer":"عُدّي بـ﴿على﴾ لتصوير الصبر نازلًا من فوق يغشاهم ويثبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-749","number":749,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"لماذا نُكّر ﴿صبرًا﴾؟","answer":"نُكّر للتعظيم والتكثير؛ طلبوا صبرًا عظيمًا يناسب شدة ما توعدهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-750","number":750,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"لماذا دعوا: ﴿وتوفنا مسلمين﴾ ولم يسألوا النجاة من فرعون؟","answer":"سألوا الثبات على الإسلام حتى الموت لأن سلامة الدين أعظم من سلامة الجسد، وقد استهانوا بعقوبة فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-751","number":751,"surah":7,"verses":[126],"verseLabel":"الأعراف: 126","question":"ما سرّ تعبيرهم بـ﴿مسلمين﴾ دون ﴿مؤمنين﴾؟","answer":"الإسلام يتضمن الاستسلام لله ظاهرًا وباطنًا والثبات على طاعته، وهو المناسب لمقام تسليم النفس عند الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279–287.","url":""}]},{"id":"s7-752","number":752,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"ما سرّ قول الملأ: ﴿أتذر موسى وقومه﴾ بعد إشارتهم بتأخيره وجمع السحرة؟","answer":"بعد فشل السحرة عاد الملأ يحرضون فرعون، متناسين أنهم أشاروا بالإمهال؛ فالاستفهام يدفعه إلى استئناف البطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-753","number":753,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"لماذا خاطب الملأ فرعون بالمضارع ﴿أتذر﴾ لا «أتركت»؟","answer":"المضارع يصور الترك قائمًا مستمرًا الآن، ويستعجل إنهاءه قبل أن ينتشر أمر موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-754","number":754,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"لماذا جمعوا بين موسى وقومه: ﴿موسى وقومه﴾؟","answer":"ضموا قومه إليه لتكبير الخطر المزعوم؛ فلم تعد القضية عندهم رجلًا منفردًا بل جماعة متنامية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-755","number":755,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"ما سرّ اتهامهم موسى وقومه بأنهم ﴿ليفسدوا في الأرض﴾ مع وصف السياق فرعون وملأه بالمفسدين؟","answer":"قلبوا الموازين فسموا دعوة التوحيد ورفع الظلم إفسادًا، مع أن السياق وصفهم هم بالمفسدين؛ وهذا من تلبيس الطغاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-756","number":756,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"ما سرّ تعبيرهم بـ﴿في الأرض﴾ مع إرادتهم أرض مصر؟","answer":"أرادوا أرض مصر المعهودة، وأطلقوا عليها ﴿الأرض﴾ لعظمها في نفوسهم وكأنها كل الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-757","number":757,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"لماذا عطفوا ﴿ويذرك وآلهتك﴾ على الإفساد؟","answer":"جعلوا ترك فرعون وآلهته غاية موازية للإفساد المزعوم، فكشفوا أن مرادهم حماية الدين السلطاني والملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-758","number":758,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"كيف يُفهم وجود ﴿آلهة﴾ لفرعون مع ادعائه: ﴿أنا ربكم الأعلى﴾؟","answer":"كان لفرعون معبودات يعبدها أو أصنامًا جعلها لقومه، مع ادعائه الربوبية العليا عليهم؛ فالطغيان يجمع التناقض ولا يلزم منه نفي كل معبود فوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-759","number":759,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"ما سرّ تعبير فرعون بصيغة الاستقبال في قوله: ﴿سنقتل أبناءهم﴾؟","answer":"السين تهديد بفعل متجدد سيستأنفه مستقبلًا، بعد أن كان قتل الأبناء قد وقع من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-760","number":760,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"ما دلالة قراءة ﴿سنقتّل أبناءهم﴾ بالتشديد؟","answer":"التشديد يدل على التكثير والتكرار؛ أي يكثر قتل الأبناء مرة بعد مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-761","number":761,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿ونستحيي نساءهم﴾ لا «ونترك نساءهم»؟","answer":"الاستحياء إبقاؤهن أحياءً للخدمة والاستذلال، فهو أخص من مجرد الترك وينطوي على قصد مهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-762","number":762,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"لماذا قابل قتل الأبناء باستحياء النساء؟","answer":"جمع بين إفناء قوة الرجال وإبقاء النساء للخدمة، لتصوير سياسة استئصالٍ واستعباد شاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-763","number":763,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"لماذا ختم فرعون بقوله: ﴿وإنا فوقهم قاهرون﴾؟","answer":"أكد قدرته بـ﴿إن﴾ والجملة الاسمية ردًا على خوف الملأ، وزعم أن قهره لبني إسرائيل ثابت لا يتغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-764","number":764,"surah":7,"verses":[127],"verseLabel":"الأعراف: 127","question":"لماذا اختار ﴿فوقهم﴾ بدل «عليهم»؟","answer":"﴿فوقهم﴾ تصور علو القاهر واستيلاءه، كأنه متمكن من أعلى، وهي أقوى تصويرًا من مجرد ﴿عليهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288–300.","url":""}]},{"id":"s7-765","number":765,"surah":7,"verses":[128],"verseLabel":"الأعراف: 128","question":"لماذا بدأ موسى جوابه لقومه بـ﴿استعينوا بالله﴾ قبل الأمر بالصبر؟","answer":"قدم الاستعانة لأنها مصدر القدرة على الصبر؛ فلا يثبتون أمام الطغيان بقوتهم وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص301–308.","url":""}]},{"id":"s7-766","number":766,"surah":7,"verses":[128],"verseLabel":"الأعراف: 128","question":"لماذا جمع بين الاستعانة والصبر؟","answer":"الاستعانة تعلق القلب بالله، والصبر ثبات الجوارح على الطريق؛ وباجتماعهما تكتمل عدة المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص301–308.","url":""}]},{"id":"s7-767","number":767,"surah":7,"verses":[128],"verseLabel":"الأعراف: 128","question":"لماذا أظهر اسم الله في ﴿استعينوا بالله﴾ ولم يقل: استعينوا به؟","answer":"أظهر اسم الله لتفخيم المستعان به وتثبيت التوحيد في النفوس أمام من يدعي الربوبية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص301–308.","url":""}]},{"id":"s7-768","number":768,"surah":7,"verses":[128],"verseLabel":"الأعراف: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الأرض لله﴾ ردًا على تهديد فرعون؟","answer":"الجملة تهدم ملك فرعون المزعوم: الأرض كلها لله، فلا يملك الطاغية أن يمنحها أو يمنعها استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص301–308.","url":""}]},{"id":"s7-769","number":769,"surah":7,"verses":[128],"verseLabel":"الأعراف: 128","question":"لماذا عرّف ﴿الأرض﴾ مع أن النزاع على مصر؟","answer":"التعريف للاستغراق؛ المراد جنس الأرض كلها، فتدخل مصر وغيرها في ملك الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص301–308.","url":""}]},{"id":"s7-770","number":770,"surah":7,"verses":[128],"verseLabel":"الأعراف: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿يورثها﴾، دون أن يقال: يعطيها؟","answer":"الإيراث انتقال الملك بعد زوال سابقه؛ فيوحي بأن سلطان فرعون عارض وأن الله ينقل الأرض لمن يشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص301–308.","url":""}]},{"id":"s7-771","number":771,"surah":7,"verses":[128],"verseLabel":"الأعراف: 128","question":"لماذا علق إيراث الأرض بالمشيئة: ﴿من يشاء من عباده﴾؟","answer":"علقها بالمشيئة لأن تداول الأرض بقدر الله وحكمته، لا بقوة فرعون ولا باستحقاق ذاتي لجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص301–308.","url":""}]},{"id":"s7-772","number":772,"surah":7,"verses":[128],"verseLabel":"الأعراف: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿من عباده﴾ بعد ﴿من يشاء﴾؟","answer":"﴿من عباده﴾ تذكر أن الوارث والموروث منه جميعًا عباد لله، وتفيد التبعيض وفق مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص301–308.","url":""}]},{"id":"s7-773","number":773,"surah":7,"verses":[128],"verseLabel":"الأعراف: 128","question":"لماذا ختم بـ﴿والعاقبة للمتقين﴾ ولم يقل: والنصر لبني إسرائيل؟","answer":"عمم الوعد للمتقين بدل تخصيص بني إسرائيل ليقرر سنة باقية: حسن النهاية لكل من اتقى، لا امتيازًا عرقيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص301–308.","url":""}]},{"id":"s7-774","number":774,"surah":7,"verses":[128],"verseLabel":"الأعراف: 128","question":"لماذا اختيرت ﴿العاقبة﴾ لا «الغلبة»؟","answer":"العاقبة تنظر إلى نهاية الطريق بعد الابتلاء، وهي أوسع من غلبة وقتية؛ تشمل النصر والنجاة وحسن المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص301–308.","url":""}]},{"id":"s7-775","number":775,"surah":7,"verses":[129],"verseLabel":"الأعراف: 129","question":"ما سرّ قول بني إسرائيل: ﴿أوذينا من قبل أن تأتينا ومن بعد ما جئتنا﴾؟","answer":"عبّروا عن ضيقهم لأن الأذى استمر قبل رسالة موسى وبعد مجيئه، فكأنهم لم يروا أثر البشارة العاجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص309–317.","url":""}]},{"id":"s7-776","number":776,"surah":7,"verses":[129],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير أولًا بـ﴿أن تأتينا﴾ ثم بـ﴿ما جئتنا﴾؟","answer":"﴿أن تأتينا﴾ مصدرية تنظر إلى زمن المجيء المتوقع، و﴿ما جئتنا﴾ تؤكد تحقق المجيء الذي أعقبه استمرار الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص309–317.","url":""}]},{"id":"s7-777","number":777,"surah":7,"verses":[129],"verseLabel":"الأعراف: 129","question":"لماذا أسندوا المجيء إلى موسى: ﴿جئتنا﴾ ولم يقولوا: بُعثت إلينا؟","answer":"نسبوا المجيء إليه لأنهم خاطبوه بما شاهدوه من حضوره بينهم، وفي العبارة مسحة عتاب على تأخر الفرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص309–317.","url":""}]},{"id":"s7-778","number":778,"surah":7,"verses":[129],"verseLabel":"الأعراف: 129","question":"لماذا أجابهم موسى بـ﴿عسى ربكم﴾ مع يقينه بوعد الله؟","answer":"﴿عسى﴾ من موسى ترجي وتعليم لقومه ألا يحددوا زمن الوعد، وهو في وعد الله يفيد قرب الرجاء مع بقاء الأمر لمشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص309–317.","url":""}]},{"id":"s7-779","number":779,"surah":7,"verses":[129],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿ربكم﴾ لا «ربي»؟","answer":"قال ﴿ربكم﴾ ليقوي صلتهم بربهم ويطمئنهم أن من يتولى إهلاك عدوهم هو مربيهم وناصرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص309–317.","url":""}]},{"id":"s7-780","number":780,"surah":7,"verses":[129],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يهلك عدوكم﴾ ولم يسمِّ فرعون؟","answer":"وصفه بالعدو يعم فرعون ومن معه ويبرز علة الهلاك، دون تعليق الرجاء بشخص قد يخلفه غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص309–317.","url":""}]},{"id":"s7-781","number":781,"surah":7,"verses":[129],"verseLabel":"الأعراف: 129","question":"لماذا جمع بين إهلاك العدو واستخلافهم: ﴿ويهلك عدوكم ويستخلفكم﴾؟","answer":"جمع إزالة المانع بإهلاك العدو ومنح البديل بالاستخلاف؛ فلا يكتمل التحرير بزوال الظالم دون تمكين المظلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص309–317.","url":""}]},{"id":"s7-782","number":782,"surah":7,"verses":[129],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿يستخلفكم في الأرض﴾ لا «يملككم الأرض»؟","answer":"الاستخلاف نيابة واختبار بعد قوم سابقين، فيحمّلهم مسؤولية العمل؛ بخلاف الملك الذي قد يوهم التملك المطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص309–317.","url":""}]},{"id":"s7-783","number":783,"surah":7,"verses":[129],"verseLabel":"الأعراف: 129","question":"لماذا ختم بـ﴿فينظر كيف تعملون﴾ بعد بشارة الاستخلاف؟","answer":"الخاتمة تحول البشارة إلى تكليف: سيظهر في الواقع كيف يشكرون نعمة التمكين ويقيمون أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص309–317.","url":""}]},{"id":"s7-784","number":784,"surah":7,"verses":[129],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف تعملون﴾ لا «ماذا تعملون»؟","answer":"﴿كيف﴾ تسأل عن هيئة العمل وصفته من طاعة وعدل أو معصية، لا عن مجرد نوع الأفعال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص309–317.","url":""}]},{"id":"s7-785","number":785,"surah":7,"verses":[130],"verseLabel":"الأعراف: 130","question":"لماذا أكد الخبر بالقسم واللام: ﴿ولقد أخذنا آل فرعون﴾؟","answer":"القسم المقدر واللام و﴿قد﴾ تؤكد أن الابتلاء وقع حقًا، تمهيدًا للعبرة من موقفهم منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص318–324.","url":""}]},{"id":"s7-786","number":786,"surah":7,"verses":[130],"verseLabel":"الأعراف: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿آل فرعون﴾ لا «فرعون وقومه»؟","answer":"﴿آل فرعون﴾ تشمل خاصته وأتباعه وأهل دولته المرتبطين بسلطانه، وتبرز أن البلاء أصاب النظام الفرعوني.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص318–324.","url":""}]},{"id":"s7-787","number":787,"surah":7,"verses":[130],"verseLabel":"الأعراف: 130","question":"لماذا عبّر عن الابتلاء بـ﴿أخذنا﴾؟","answer":"الأخذ يصور إحاطة الشدة بهم وتمكنها منهم، مع أنه ابتلاء دون الاستئصال الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص318–324.","url":""}]},{"id":"s7-788","number":788,"surah":7,"verses":[130],"verseLabel":"الأعراف: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿بالسنين﴾، وما المراد بالسنين هنا؟","answer":"السنون هنا سنوات الجدب والقحط؛ وغلب اللفظ عليها حتى صار يشعر بطول الشدة وتتابعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص318–324.","url":""}]},{"id":"s7-789","number":789,"surah":7,"verses":[130],"verseLabel":"الأعراف: 130","question":"لماذا جمع بين ﴿السنين﴾ و﴿نقص من الثمرات﴾؟","answer":"جمع الجدب العام الذي يمنع الزرع مع نقص الثمر الموجود بسبب الآفات، ليستوعب أصول معاشهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص318–324.","url":""}]},{"id":"s7-790","number":790,"surah":7,"verses":[130],"verseLabel":"الأعراف: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿نقص من الثمرات﴾ بزيادة ﴿من﴾؟","answer":"﴿من﴾ تبعيضية، أي نقص بعض الثمرات ولم يستأصلها كلها؛ ليبقى لهم مجال للتذكر والرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص318–324.","url":""}]},{"id":"s7-791","number":791,"surah":7,"verses":[130],"verseLabel":"الأعراف: 130","question":"لماذا ختم بـ﴿لعلهم يذكرون﴾ لا ﴿لعلهم يضرعون﴾ كما في الآية 94؟","answer":"خُتم هنا بالتذكر لأن الآيات توالت على آل فرعون ليعتبروا بعهد الله وإنذاره، أما آية القرى فكان المقصود انكسارهم وتضرعهم أولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص318–324.","url":""}]},{"id":"s7-792","number":792,"surah":7,"verses":[130],"verseLabel":"الأعراف: 130","question":"لماذا اختيرت صيغة ﴿يذكرون﴾؟","answer":"المضارع يدل على تجدد التذكر كلما رأوا آية أو أصابتهم شدة، وهو الغاية المرجوة من الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص318–324.","url":""}]},{"id":"s7-793","number":793,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا جاءتهم الحسنة﴾ بأداة التحقيق والمفاجأة؟","answer":"﴿إذا﴾ للتحقق والتكرر، والفاء تصل مجيء النعمة بقولهم فورًا؛ فما إن تأتي حتى ينسبوها لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-794","number":794,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"لماذا عُرّفت ﴿الحسنة﴾ و﴿السيئة﴾؟","answer":"التعريف للعهد الجنسي؛ الحسنة هي الخصب والرخاء المعروفان، والسيئة هي الجدب والشدة المقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-795","number":795,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"ما سرّ تعبيرهم في الحسنة بقولهم: ﴿لنا هذه﴾؟","answer":"قولهم ﴿لنا هذه﴾ ادعاء للاستحقاق الذاتي، كأن النعمة حق ثابت لهم لا فضل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-796","number":796,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"لماذا أشاروا إلى الحسنة بـ﴿هذه﴾؟","answer":"الإشارة تقرب الحسنة الحاضرة وتدل على رضاهم بها واستحواذهم النفسي عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-797","number":797,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن تصبهم سيئة﴾ بـ﴿إن﴾، بينما قال في الحسنة ﴿فإذا جاءتهم﴾؟","answer":"جاءت الحسنة بـ﴿إذا﴾ الدالة على التحقق لكثرتها واتساعها، والسيئة بـ﴿إن﴾ التي تستعمل في المحتمل والقليل، تصويرًا لنظرتهم المنحازة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-798","number":798,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى في الحسنة ﴿جاءتهم﴾، وفي السيئة ﴿تصبهم﴾؟","answer":"﴿جاءتهم﴾ تلائم الحسنة كوافد مرغوب، و﴿تصبهم﴾ تصور السيئة كضربة تقع عليهم؛ فاختلاف الفعلين يرسم اختلاف تلقيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-799","number":799,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"ما سرّ تشاؤمهم بـ﴿موسى ومن معه﴾، وإغفالهم النظر في أعمالهم؟","answer":"تشاءموا بموسى ومن معه، فجعلوا مجيئهم سبب الشدة، بدل أن يردّوا المصائب إلى كفرهم وأعمالهم؛ فجاء الرد بأن نصيبهم وما يحل بهم بتقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-800","number":800,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿ألا إنما طائرهم عند الله﴾؟","answer":"افتتحت الجملة بـ﴿ألا﴾ للتنبيه، وجاء القصر بـ﴿إنما﴾ لإبطال زعمهم: ما يصيبهم من شؤم وعقاب عند الله، لا من موسى ومن معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-801","number":801,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"لماذا كرر مادة الطير في ﴿يطيروا﴾ و﴿طائرهم﴾؟","answer":"في ﴿يطيروا﴾ حكاية لتشاؤمهم الباطل، وفي ﴿طائرهم﴾ مشاكلة لهم مع نقل اللفظ إلى سببه الحق: نصيبهم المترتب على أعمالهم عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-802","number":802,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿عند الله﴾ لا «من الله»؟","answer":"﴿عند الله﴾ تفيد أن أمر حظهم وجزائهم في حكم الله وتقديره، لا أن موسى هو منشأ ما أصابهم؛ فالمقام مقام رد الأمر إلى تدبيره وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-803","number":803,"surah":7,"verses":[131],"verseLabel":"الأعراف: 131","question":"لماذا ختم بـ﴿ولكن أكثرهم لا يعلمون﴾؟","answer":"نفت الخاتمة عن أكثرهم العلم بأن ما أصابهم من عند الله وبسبب أعمالهم، وأشعرت بأن قليلًا منهم يعلم الحق ولكنه لا يعمل بمقتضاه عنادًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص325–337.","url":""}]},{"id":"s7-804","number":804,"surah":7,"verses":[132],"verseLabel":"الأعراف: 132","question":"ما دلالة قولهم: ﴿مهما تأتنا به من آية﴾ بدل «أي آية تأتنا»؟","answer":"﴿مهما﴾ من ألفاظ العموم؛ فالمعنى: أيّ آية تأتنا بها، مهما كانت، لن نؤمن، وفيه إعلان العناد قبل النظر في الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص338–342.","url":""}]},{"id":"s7-805","number":805,"surah":7,"verses":[132],"verseLabel":"الأعراف: 132","question":"ما الذي يكشفه قولهم لموسى: ﴿لتسحرنا بها﴾؟","answer":"سمّوا الآية سحرًا، وزعموا أن غرض موسى بها صرفهم عما هم عليه؛ فحوّلوا الدليل إلى تهمة ليثبتوا على الإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص338–342.","url":""}]},{"id":"s7-806","number":806,"surah":7,"verses":[132],"verseLabel":"الأعراف: 132","question":"لماذا أعادوا الضمير في ﴿به من آية﴾ ثم ﴿بها﴾؟","answer":"الضمير في ﴿به﴾ يعود إلى ما يأتي به موسى، ثم جاءت ﴿من آية﴾ بيانًا له، والضمير في ﴿بها﴾ يعود إلى الآية بعد بيانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص338–342.","url":""}]},{"id":"s7-807","number":807,"surah":7,"verses":[132],"verseLabel":"الأعراف: 132","question":"ما سرّ تعبيرهم: ﴿فما نحن لك بمؤمنين﴾ بدل «فلن نؤمن بك»؟","answer":"الجملة الاسمية مع الباء الزائدة في ﴿بمؤمنين﴾ أشد توكيدًا لنفي الإيمان من قولهم: لن نؤمن؛ فهي تصور تمكّن العناد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص338–342.","url":""}]},{"id":"s7-808","number":808,"surah":7,"verses":[132],"verseLabel":"الأعراف: 132","question":"لماذا قدّموا ﴿لك﴾ على ﴿بمؤمنين﴾؟","answer":"تقديم ﴿لك﴾ يخص موسى بالرفض ويبرز عنادهم لشخصه ورسالته: فما نحن لك، على وجه الخصوص، بمصدقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص338–342.","url":""}]},{"id":"s7-809","number":809,"surah":7,"verses":[132],"verseLabel":"الأعراف: 132","question":"لماذا عبّروا باسم الفاعل ﴿مؤمنين﴾؟","answer":"اسم الفاعل في ﴿مؤمنين﴾ يثبت نفي صفة الإيمان عنهم، لا مجرد نفي فعل يقع مرة؛ وهو ملائم لإصرارهم الدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص338–342.","url":""}]},{"id":"s7-810","number":810,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"لماذا عطف إرسال الآيات بالفاء: ﴿فأرسلنا عليهم﴾؟","answer":"الفاء تفيد تعقيب العقوبات على عنادهم المعلن في الآية السابقة، فكان الإرسال جوابًا عمليًا عن قولهم إنهم لن يؤمنوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-811","number":811,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"لماذا عُدّيت الآيات بـ﴿على﴾: ﴿أرسلنا عليهم﴾؟","answer":"عدّي الإرسال بـ﴿على﴾ لأن هذه الآيات عقوبات نازلة مستعلية محيطة بهم، لا آيات مسوقة لهم على جهة التكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-812","number":812,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"لماذا رتبت العقوبات: ﴿الطوفان والجراد والقمل والضفادع والدم﴾ بهذا الترتيب؟","answer":"ذكرت العقوبات في تتابعها الذي نزلت به، وانتقلت من آفة عامة غامرة إلى ما يصيب الزروع والأبدان والمعاش، حتى انتهت إلى الدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-813","number":813,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"لماذا بدأ بالطوفان؟","answer":"بدأ بالطوفان لأنه عقوبة غامرة واسعة تعم الأرض والزرع والمساكن، فافتتح به سلسلة البلاء العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-814","number":814,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"لماذا أفردت أسماء الآفات مع كثرتها؟","answer":"أفرد كل اسم لأنه اسم جنس يشمل أفرادًا كثيرة؛ فالجراد والقمل والضفادع والدم تدل على جنس الآفة المستولي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-815","number":815,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"لماذا خُتمت القائمة بـ﴿الدم﴾؟","answer":"ختم بالدم لأنه بلغ إلى أصل الماء الذي تقوم به الحياة، فصار ما يشربونه دمًا، وكان أبلغ في التضييق عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-816","number":816,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"لماذا وصفها بـ﴿آيات مفصلات﴾؟","answer":"﴿مفصلات﴾ أي مبينات ظاهرات، يفصل بعضها عن بعض، تأتي آية بعد آية وبينها مهلة ليعتبروا ويرجعوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-817","number":817,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"لماذا جاءت ﴿مفصلات﴾ بصيغة التفعيل؟","answer":"صيغة التفعيل تدل على قوة الفصل والتبيين؛ فقد جاءت الآيات متميزة متتابعة، لا حادثة ملتبسة يمكن صرفها عن دلالتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-818","number":818,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿فاستكبروا﴾ بعد ظهور الآيات؟","answer":"الفاء تكشف سرعة انتقالهم من مشاهدة الآيات المفصلة إلى الاستكبار بدل الإيمان، فكان ردهم عنادًا لا خفاءً في الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-819","number":819,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"لماذا ختم بـ﴿وكانوا قومًا مجرمين﴾؟","answer":"الخاتمة تبين أن الاستكبار ليس عارضًا؛ فقد كانوا راسخين في الإجرام، ولذلك قابلوا الآيات الواضحة بالعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-820","number":820,"surah":7,"verses":[133],"verseLabel":"الأعراف: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿قومًا مجرمين﴾ بدل «وكانوا مجرمين»؟","answer":"إدخال ﴿قومًا﴾ يصور الإجرام صفة غالبة في جماعتهم، كأنهم قوم شأنهم الإجرام، وهو أبلغ من مجرد الإخبار عن أفراد بأنهم مجرمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343–352.","url":""}]},{"id":"s7-821","number":821,"surah":7,"verses":[134],"verseLabel":"الأعراف: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما وقع عليهم الرجز﴾، فصوّر العذاب واقعًا عليهم؟","answer":"﴿وقع﴾ يصور الرجز كحمل نازل استقر فوقهم وأحاط بهم، فيجسد شدة العذاب وتمكنه منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص353–362.","url":""}]},{"id":"s7-822","number":822,"surah":7,"verses":[134],"verseLabel":"الأعراف: 134","question":"لماذا عبّر بـ﴿الرجز﴾ بعد تسمية الآيات الخمس؟","answer":"﴿الرجز﴾ اسم للعذاب الشديد المضطرب؛ فجمع الآفات السابقة تحت وصف واحد يبرز كونها عقوبة مهلكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص353–362.","url":""}]},{"id":"s7-823","number":823,"surah":7,"verses":[134],"verseLabel":"الأعراف: 134","question":"لماذا نادوا: ﴿يا موسى﴾ بعد أن اتهموه بالسحر؟","answer":"لما مسهم العذاب عادوا إلى من اتهموه بالسحر، ونادوه باسمه استمالةً وطلبًا للنجدة؛ فكشف البلاء اضطرارهم إلى الاعتراف بمكان دعائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص353–362.","url":""}]},{"id":"s7-824","number":824,"surah":7,"verses":[134],"verseLabel":"الأعراف: 134","question":"ما الذي تكشفه إضافتهم الرب إلى موسى في قولهم: ﴿ادع لنا ربك﴾ لا «ربنا»؟","answer":"إضافتهم الرب إلى موسى في ﴿ربك﴾ لا ﴿ربنا﴾ تكشف أنهم لم يدخلوا بعد في الإيمان، وإنما طلبوا كشف الضر ممن عرفوا قربه من ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص353–362.","url":""}]},{"id":"s7-825","number":825,"surah":7,"verses":[134],"verseLabel":"الأعراف: 134","question":"ما دلالة قولهم: ﴿بما عهد عندك﴾، وما المراد بالعهد؟","answer":"العهد هو ما أعطاه الله موسى من وعد بإجابة دعائه أو ما خصه به من النبوة والقرب؛ فطلبوا أن يدعو بمقتضى ذلك العهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص353–362.","url":""}]},{"id":"s7-826","number":826,"surah":7,"verses":[134],"verseLabel":"الأعراف: 134","question":"لماذا قدّموا رفع الرجز: ﴿لئن كشفت عنا الرجز لنؤمنن لك﴾؟","answer":"جعلوا كشف الرجز شرطًا سابقًا، ثم رتبوا عليه وعد الإيمان والإرسال؛ فدل ترتيبهم على أن همهم العاجل النجاة من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص353–362.","url":""}]},{"id":"s7-827","number":827,"surah":7,"verses":[134],"verseLabel":"الأعراف: 134","question":"لماذا اختير ﴿كشفت﴾ لا «رفعت»؟","answer":"الكشف إزالة ما يغطي ويحيط، فصور الرجز كغطاء ثقيل أطبق عليهم ثم أزيل، وهو أنسب من الرفع المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص353–362.","url":""}]},{"id":"s7-828","number":828,"surah":7,"verses":[134],"verseLabel":"الأعراف: 134","question":"لماذا أكدوا وعد الإيمان والإرسال بالنون واللام؟","answer":"اللام ونون التوكيد الثقيلة في ﴿لنؤمنن﴾ و﴿لنرسلن﴾ غلظتا وعدهم، لتظهر المفارقة حين نكثوه بعد كشف الرجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص353–362.","url":""}]},{"id":"s7-829","number":829,"surah":7,"verses":[134],"verseLabel":"الأعراف: 134","question":"ما سرّ تعبيرهم: ﴿لنؤمنن لك﴾ لا «بك»؟","answer":"الإيمان المعدّى باللام هنا بمعنى التصديق والانقياد لموسى فيما جاء به، لا مجرد الإقرار بوجوده؛ أي لنصدقن دعوتك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص353–362.","url":""}]},{"id":"s7-830","number":830,"surah":7,"verses":[134],"verseLabel":"الأعراف: 134","question":"لماذا عطفوا ﴿ولنرسلن معك بني إسرائيل﴾ على الإيمان؟","answer":"جمعوا بين حق الله بالإيمان وحق بني إسرائيل بإطلاقهم؛ لأن موسى طالبهم بالأمرين، فتعهدوا بهما معًا رجاء كشف البلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص353–362.","url":""}]},{"id":"s7-831","number":831,"surah":7,"verses":[135],"verseLabel":"الأعراف: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما كشفنا عنهم الرجز﴾ بالفاء؟","answer":"الفاء تصل الكشف مباشرة بدعاء موسى ووعدهم، وتبين سرعة إجابة الطلب وإقامة الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص363–370.","url":""}]},{"id":"s7-832","number":832,"surah":7,"verses":[135],"verseLabel":"الأعراف: 135","question":"لماذا أعاد لفظ ﴿الرجز﴾ ظاهرًا ولم يضمره؟","answer":"أعيد ﴿الرجز﴾ لإبراز أن الذي كشف هو عين العذاب الذي ألجأهم إلى الوعد، فلا يبقى لهم عذر في النكث.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص363–370.","url":""}]},{"id":"s7-833","number":833,"surah":7,"verses":[135],"verseLabel":"الأعراف: 135","question":"لماذا قيد الكشف بـ﴿إلى أجل هم بالغوه﴾؟","answer":"بيّن القيد أن الكشف إمهال مؤقت إلى نهاية مقدرة سيبلغونها حتمًا، لا نجاة مطلقة من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص363–370.","url":""}]},{"id":"s7-834","number":834,"surah":7,"verses":[135],"verseLabel":"الأعراف: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿هم بالغوه﴾ بضمير الفصل أو التقوية؟","answer":"إظهار ﴿هم﴾ يقوي نسبة البلوغ إليهم ويؤكد أنهم لا يفلتون من الأجل المضروب لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص363–370.","url":""}]},{"id":"s7-835","number":835,"surah":7,"verses":[135],"verseLabel":"الأعراف: 135","question":"لماذا جاءت المفاجأة: ﴿إذا هم ينكثون﴾؟","answer":"﴿إذا﴾ الفجائية تصور أنهم ما إن وجدوا العافية حتى بادروا إلى نقض العهد، من غير تردد أو وفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص363–370.","url":""}]},{"id":"s7-836","number":836,"surah":7,"verses":[135],"verseLabel":"الأعراف: 135","question":"لماذا عبّر بالمضارع ﴿ينكثون﴾؟","answer":"المضارع يستحضر مشهد النكث ويصوره عادة متجددة منهم كلما كشف عنهم البلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص363–370.","url":""}]},{"id":"s7-837","number":837,"surah":7,"verses":[135],"verseLabel":"الأعراف: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿ينكثون﴾ لا «يخلفون»؟","answer":"النكث أصله نقض المفتول بعد إحكامه، فصوّر إفسادهم للعهد المؤكد كحل حبل محكم، وهو أبلغ من مطلق الإخلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص363–370.","url":""}]},{"id":"s7-838","number":838,"surah":7,"verses":[136],"verseLabel":"الأعراف: 136","question":"لماذا بدأت العقوبة بـ﴿فانتقمنا منهم﴾ بعد تكرر النكث؟","answer":"الفاء تجعل الانتقام نتيجة متعقبة لتكرر النكث بعد تمام الحجة، فلا يبدو الإغراق عقوبة بلا سبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص371–381.","url":""}]},{"id":"s7-839","number":839,"surah":7,"verses":[136],"verseLabel":"الأعراف: 136","question":"ما سرّ التعبير في قوله تعالى: ﴿انتقمنا منهم﴾، دون أن يقال: عذبناهم؟","answer":"الانتقام مجازاة على جرم سابق واستيفاء للحق، فدل على أن الإغراق جزاء تكذيبهم ونكثهم، لا مجرد إيقاع عذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص371–381.","url":""}]},{"id":"s7-840","number":840,"surah":7,"verses":[136],"verseLabel":"الأعراف: 136","question":"لماذا فصّل الانتقام بقوله: ﴿فأغرقناهم في اليم﴾؟","answer":"جاء ﴿فأغرقناهم﴾ بيانًا لصورة الانتقام وكيفية وقوعه، بعد ذكره إجمالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص371–381.","url":""}]},{"id":"s7-841","number":841,"surah":7,"verses":[136],"verseLabel":"الأعراف: 136","question":"لماذا اختير ﴿اليم﴾ لا «البحر»؟","answer":"اليم اسم للماء الكثير العميق الذي لا يدرك قعره، وهو يلائم مقام الإغراق والهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص371–381.","url":""}]},{"id":"s7-842","number":842,"surah":7,"verses":[136],"verseLabel":"الأعراف: 136","question":"ما سرّ التعبير في قوله تعالى: ﴿في اليم﴾ لا «باليم»؟","answer":"﴿في اليم﴾ تصور دخولهم في جوف الماء وإحاطته بهم من كل جهة، لا مجرد جعله آلة للإغراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص371–381.","url":""}]},{"id":"s7-843","number":843,"surah":7,"verses":[136],"verseLabel":"الأعراف: 136","question":"لماذا صرّح بسبب الإغراق: ﴿بأنهم كذبوا بآياتنا﴾؟","answer":"صرح بالسبب ليبين عدل العقوبة وأنها جزاء تكذيب مقصود بالآيات، لا حادثة منفصلة عن أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص371–381.","url":""}]},{"id":"s7-844","number":844,"surah":7,"verses":[136],"verseLabel":"الأعراف: 136","question":"لماذا جمع بين التكذيب والغفلة: ﴿كذبوا بآياتنا وكانوا عنها غافلين﴾؟","answer":"التكذيب فعلهم الظاهر في مقابلة الحجج، والغفلة إعراضهم المستمر عن دلالتها وعواقبها؛ فجمع بين الجحود وترك الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص371–381.","url":""}]},{"id":"s7-845","number":845,"surah":7,"verses":[136],"verseLabel":"الأعراف: 136","question":"كيف وُصفوا بالغفلة مع أنهم رأوا الآيات وطلبوا كشف العذاب؟","answer":"الغفلة هنا ليست عدم رؤية الآيات، بل الإعراض عن موجبها وترك الاعتبار بها؛ فقد شاهدوها ثم عاملوها معاملة من لا ينتبه لدلالتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص371–381.","url":""}]},{"id":"s7-846","number":846,"surah":7,"verses":[136],"verseLabel":"الأعراف: 136","question":"ما سرّ التعبير في قوله تعالى: ﴿عنها غافلين﴾ بتقديم الجار والمجرور؟","answer":"تقديم ﴿عنها﴾ يبرز أن الآيات، مع وضوحها وكثرتها، هي عين ما أعرضوا عنه؛ وفيه تشديد للتوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص371–381.","url":""}]},{"id":"s7-847","number":847,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿وأورثنا القوم الذين كانوا يستضعفون﴾، دون أن يقال: وأعطينا بني إسرائيل؟","answer":"الإيراث تمليك يعقب زوال المالك السابق من غير كلفة على الوارث، فناسب انتقال أرض الجبارين إلى المستضعفين، وذكرهم بوصفهم السابق يبرز انقلاب الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-848","number":848,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"لماذا وصفهم بالماضي المستمر: ﴿كانوا يستضعفون﴾؟","answer":"﴿كانوا يستضعفون﴾ تدل على أن الاستضعاف كان حالة مستمرة متكررة قبل التمكين، لا واقعة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-849","number":849,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"لماذا بُني ﴿يستضعفون﴾ للمجهول؟","answer":"بني الفعل للمجهول لأن المقصود تصوير حالهم كمستضعفين وإبراز التحول الذي صنعه الله، لا إعادة ذكر المستضعِفين وقد عرفوا من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-850","number":850,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿مشارق الأرض ومغاربها﴾ بالجمع؟","answer":"الجمع يلحظ تعدد جهات الشروق والغروب واختلافها في الأرض الموروثة، فيفيد سعتها وشمول التمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-851","number":851,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"لماذا جمع بين المشارق والمغارب؟","answer":"ذكر المشارق والمغارب إحاطة بطرفي الأرض، أي أورثهم نواحيها الممتدة كلها، لا جهة واحدة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-852","number":852,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"لماذا وصف الأرض بـ﴿التي باركنا فيها﴾؟","answer":"هي أرض الشام التي بارك الله فيها بالخصب والثمار ومنازل الأنبياء؛ والوصف يبين قيمة ما أورثوه بعد الاستضعاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-853","number":853,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿وتمت كلمة ربك الحسنى﴾، وكيف تتم الكلمة؟","answer":"تمام الكلمة تحقق مضمون الوعد كاملًا في الواقع؛ فقد أنجز الله وعده بنجاة المستضعفين وتمكينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-854","number":854,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"لماذا أضيف الرب إلى النبي: ﴿ربك﴾ بعد أن كان الخطاب عن بني إسرائيل؟","answer":"إضافة الرب إلى النبي ﷺ في ﴿ربك﴾ تسلية له وتثبيت: فالرب الذي أنجز وعده لبني إسرائيل سينجز وعده لرسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-855","number":855,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"لماذا وُصفت الكلمة بـ﴿الحسنى﴾؟","answer":"﴿الحسنى﴾ لأن الكلمة وعد جميل بالنصر والتمكين، ولأن عاقبتها الحسنى ظهرت بتمامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-856","number":856,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿بما صبروا﴾ لا «لأنهم استُضعفوا»؟","answer":"علّق تمام الوعد بصبرهم ليبين أن التمكين جزاء ثباتهم على البلاء، لا لمجرد وقوع الاستضعاف عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-857","number":857,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿ودمرنا ما كان يصنع فرعون وقومه﴾؟","answer":"التدمير إهلاك الشيء وإفساد بنائه، فشمل ما أنشأه فرعون وقومه من صنائع ومنشآت وما أقاموه من سلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-858","number":858,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"لماذا أفرد الفعل مع فرعون: ﴿يصنع فرعون وقومه﴾؟","answer":"أفرد ﴿يصنع﴾ لأن فرعون هو الرأس المتبوع، وعطف قومه عليه تبعًا؛ فصناعتهم تابعة لأمره وسلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-859","number":859,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿يصنع﴾ بالمضارع و﴿كانوا يعرشون﴾ بالماضي الناقص والمضارع؟","answer":"﴿كان يصنع﴾ يصور الصنع المتجدد الذي كان فرعون وقومه يزاولونه، و﴿كانوا يعرشون﴾ يدل كذلك على استمرار رفع الأبنية والكروم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-860","number":860,"surah":7,"verses":[137],"verseLabel":"الأعراف: 137","question":"ما الفرق بين ﴿ما كان يصنع فرعون وقومه﴾ و﴿ما كانوا يعرشون﴾؟","answer":"الصنع أعم، فيشمل تدبيرهم وأعمالهم ومنشآتهم؛ والعروش أخص بما كانوا يرفعونه من أبنية أو سقوف وكروم، فجمع النص العام والخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص382–397.","url":""}]},{"id":"s7-861","number":861,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاوزنا ببني إسرائيل البحر﴾، فعُدّي التجاوز بالباء؟","answer":"الباء للتعدية والمصاحبة؛ أي جعلنا بني إسرائيل يجاوزون البحر سالمين، ففيها معنى أن الله نقلهم بنفسه من شاطئ إلى آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-862","number":862,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"لماذا أظهر ﴿بني إسرائيل﴾ بدل الضمير بعد ذكرهم في الآية السابقة؟","answer":"أظهر اسم ﴿بني إسرائيل﴾ لاستئناف مرحلة جديدة من قصتهم والتنبيه إلى هوية القوم الذين قابلوا نعمة النجاة بهذا الطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-863","number":863,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتوا على قوم﴾ لا «فمروا بقوم»؟","answer":"﴿أتوا على قوم﴾ تفيد الوصول إليهم والاستعلاء على مكانهم والمرور بمحلتهم، لا مجرد المرور العابر من بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-864","number":864,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"لماذا نُكّر ﴿قوم﴾؟","answer":"نُكّر ﴿قوم﴾ لأن هويتهم ليست موضع العبرة؛ المقصود حالهم العجيبة في ملازمة الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-865","number":865,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿يعكفون على أصنام لهم﴾؟","answer":"العكوف هو الملازمة مع الإقبال والتعظيم؛ فصورت الآية دوام إقامتهم على أصنام يعبدونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-866","number":866,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"لماذا عُدّي العكوف بـ﴿على﴾ لا بـ«عند»؟","answer":"عدي العكوف بـ﴿على﴾ لما فيه من الملازمة والإقبال والمواظبة على الشيء، وهي أبلغ من مجرد الكون عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-867","number":867,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"لماذا وصف الأصنام بأنها ﴿لهم﴾؟","answer":"﴿لهم﴾ تكشف اختصاصهم بهذه الأصنام واتخاذهم إياها لأنفسهم، مع أنها مصنوعات مملوكة لهم لا آلهة تملكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-868","number":868,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"كيف طلب بنو إسرائيل إلهًا بعد أن جاوزوا البحر ورأوا هلاك فرعون؟","answer":"كان أثر البيئة الوثنية لا يزال في نفوسهم، فلما رأوا قومًا يعظمون أصنامًا حنوا إلى ما ألفوه، وكشف الطلب رسوخ الجهل رغم الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-869","number":869,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"ما دلالة طلبهم: ﴿اجعل لنا إلهًا﴾، وهل يُجعل الإله؟","answer":"طلبهم ﴿اجعل﴾ لا يعني إمكان خلق إله حق، بل طلبوا أن يعين لهم معبودًا محسوسًا يتخذونه إلهًا كما اتخذ أولئك أصنامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-870","number":870,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"ما سرّ قولهم: ﴿كما لهم آلهة﴾ بالجمع بعد طلب إله واحد؟","answer":"طلبوا معبودًا واحدًا لجماعتهم، وشبهوا حالهم بقوم لهم أصنام متعددة؛ فالمقصود مماثلتهم في أصل اتخاذ المعبود المحسوس لا في العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-871","number":871,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"ما مناسبة جواب موسى: ﴿إنكم قوم تجهلون﴾؟","answer":"جاء الرد مؤكدًا بـ﴿إن﴾، ووصفهم بأنهم ﴿قوم تجهلون﴾ لأن طلبهم تعلق بأصل التوحيد بعد مشاهدة أعظم آيات النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-872","number":872,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿تجهلون﴾ بالمضارع لا «جاهلون»؟","answer":"المضارع في ﴿تجهلون﴾ يصور الجهل فعلًا حاضرًا ظهر في طلبهم ومتجددًا منهم، لا صفة ثابتة لا تزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-873","number":873,"surah":7,"verses":[138],"verseLabel":"الأعراف: 138","question":"لماذا التفت موسى من خطابهم إلى الغيبة في بعض توجيهات السياق المتصلة؟","answer":"انتقل الخطاب بحسب المقام من مواجهة أصحاب الطلب إلى الحديث عن أهل الأصنام وبيان مصير عملهم، فتميّز المخاطَب المحذَّر من النموذج المذموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص398–414.","url":""}]},{"id":"s7-874","number":874,"surah":7,"verses":[139],"verseLabel":"الأعراف: 139","question":"لماذا بدأ إبطال عبادة الأصنام باسم الإشارة: ﴿إن هؤلاء﴾؟","answer":"اسم الإشارة يحضر أهل الأصنام أمام السامعين كأنهم مشاهدون، ثم يصدر الحكم على حالهم: ما هم فيه إلى هلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص415–422.","url":""}]},{"id":"s7-875","number":875,"surah":7,"verses":[139],"verseLabel":"الأعراف: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿متبر ما هم فيه﴾، وما دلالة «متبر»؟","answer":"﴿متبر﴾ أي مهلك مدمر؛ فالمعنى أن ما هم فيه من دين وعبادة مصيره الزوال والهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص415–422.","url":""}]},{"id":"s7-876","number":876,"surah":7,"verses":[139],"verseLabel":"الأعراف: 139","question":"لماذا جاء ﴿متبر﴾ اسمًا لا فعلًا؟","answer":"اسم المفعول ﴿متبر﴾ يثبت الحكم ويصوره مآلًا محققًا قائمًا، لا فعلًا عارضًا قد يقع أو لا يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص415–422.","url":""}]},{"id":"s7-877","number":877,"surah":7,"verses":[139],"verseLabel":"الأعراف: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿ما هم فيه﴾ بدل «عبادتهم»؟","answer":"﴿ما هم فيه﴾ يصور العبادة الباطلة كظرف أحاط بهم واستغرق حياتهم، وهو أوسع من تسمية فعل العبادة وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص415–422.","url":""}]},{"id":"s7-878","number":878,"surah":7,"verses":[139],"verseLabel":"الأعراف: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿وباطل ما كانوا يعملون﴾ بعد ﴿متبر ما هم فيه﴾؟","answer":"الأول يحكم على المعبودات والحال التي لابسوها بالهلاك، والثاني يحكم على أعمالهم نفسها بالبطلان؛ فشمل فساد المعبود والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص415–422.","url":""}]},{"id":"s7-879","number":879,"surah":7,"verses":[139],"verseLabel":"الأعراف: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿كانوا يعملون﴾ لا «عملوا»؟","answer":"﴿كانوا يعملون﴾ تدل على رسوخ العمل وتكرره زمنًا، ومع ذلك لم يمنحه التكرار قيمة؛ فهو باطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص415–422.","url":""}]},{"id":"s7-880","number":880,"surah":7,"verses":[139],"verseLabel":"الأعراف: 139","question":"ما الفرق بين ﴿متبر ما هم فيه﴾ و﴿باطل ما كانوا يعملون﴾؟","answer":"﴿متبر﴾ يبين مآل ما هم فيه إلى التدمير، و﴿باطل﴾ يبين أن أعمالهم لا حقيقة نافعة لها ولا ثواب؛ فالأول للعاقبة والثاني للقيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص415–422.","url":""}]},{"id":"s7-881","number":881,"surah":7,"verses":[140],"verseLabel":"الأعراف: 140","question":"ما دلالة الاستفهام في قول موسى: ﴿أغير الله أبغيكم إلهًا﴾؟","answer":"الاستفهام إنكاري تعجبي: أيستبدل موسى بالله إلهًا آخر يطلبه لهم؟ وفيه إظهار فظاعة طلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص423–431.","url":""}]},{"id":"s7-882","number":882,"surah":7,"verses":[140],"verseLabel":"الأعراف: 140","question":"لماذا قدّم ﴿غير الله﴾ على الفعل؟","answer":"قدم ﴿غير الله﴾ لأنه محور الإنكار؛ فالمنكر أولًا أن يكون المطلوب أحدًا غير الله، أيًا كان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص423–431.","url":""}]},{"id":"s7-883","number":883,"surah":7,"verses":[140],"verseLabel":"الأعراف: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿أبغيكم﴾ لا «أجعل لكم» كما طلبوا؟","answer":"﴿أبغيكم﴾ تعني أطلب لكم وألتمس، وفيها رد طلبهم بصورته: أتطلبون مني أن أبحث لكم عن معبود غير الله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص423–431.","url":""}]},{"id":"s7-884","number":884,"surah":7,"verses":[140],"verseLabel":"الأعراف: 140","question":"لماذا نكّر ﴿إلهًا﴾ في سياق الإنكار؟","answer":"التنكير في سياق الاستفهام الإنكاري يعم أي إله مزعوم؛ فلا يصلح لهم غير الله واحدًا كان أو متعددًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص423–431.","url":""}]},{"id":"s7-885","number":885,"surah":7,"verses":[140],"verseLabel":"الأعراف: 140","question":"لماذا عقب بقوله: ﴿وهو فضلكم على العالمين﴾؟","answer":"ذكّرهم بتفضيل الله لهم بالنعم والنجاة ليقيم الحجة من واقع إحسانه إليهم: فكيف يطلبون غير المنعم إلهًا؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص423–431.","url":""}]},{"id":"s7-886","number":886,"surah":7,"verses":[140],"verseLabel":"الأعراف: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿فضلكم﴾ بالماضي؟","answer":"الماضي في ﴿فضلكم﴾ يقرر نعمة تحققت وشاهدوها، فتقوم بها الحجة عليهم ولا تبقى وعدًا منتظرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص423–431.","url":""}]},{"id":"s7-887","number":887,"surah":7,"verses":[140],"verseLabel":"الأعراف: 140","question":"كيف يُفهم قوله تعالى: ﴿على العالمين﴾ مع وجود أمم أفضل منهم؟","answer":"المراد عالمو زمانهم، أو التفضيل بما خصوا به من النجاة والآيات في ذلك المقام، لا أنهم أفضل من كل أمة في كل زمان وعلى كل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص423–431.","url":""}]},{"id":"s7-888","number":888,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"لماذا انتقل الخطاب إلى ﴿وإذ أنجيناكم من آل فرعون﴾؟","answer":"أعيد تذكيرهم بالإنجاء من فرعون عقب إنكار طلبهم إلهًا؛ ليقابل قبح الشرك بعظمة النعمة التي تلقوها من ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-889","number":889,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿أنجيناكم﴾ هنا، وفي البقرة: ﴿نجيناكم﴾؟","answer":"﴿أنجيناكم﴾ و﴿نجيناكم﴾ بمعنى التخليص، وزيادة المبنى في ﴿نجيناكم﴾ بالتضعيف تلائم مقام تعداد النعم وتفصيل شدة التخليص في البقرة، أما الأعراف فجاءت بالصيغة الأخف في سياق موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-890","number":890,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"لماذا عُلّق الإنجاء بالمخاطبين: ﴿أنجيناكم﴾ لا بإخراجهم من البحر فقط؟","answer":"جعل الإنجاء واقعًا عليهم أنفسهم لأنه لم يكن مجرد خروج مكاني، بل تخليصًا كاملًا من العذاب والاستعباد والهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-891","number":891,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿من آل فرعون﴾ لا «من فرعون»؟","answer":"﴿آل فرعون﴾ تشمل فرعون وملأه وأتباعه القائمين بأمره، فالعذاب كان نظامًا تمارسه جماعته لا فعل شخص واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-892","number":892,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿يسومونكم سوء العذاب﴾، وما صورة «السوم»؟","answer":"السوم إلزام الشيء وإدامته؛ فصورت العبارة آل فرعون يذيقونهم العذاب مرارًا ويكلفونهم صنوفه بلا انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-893","number":893,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"لماذا أضيف ﴿سوء﴾ إلى ﴿العذاب﴾؟","answer":"الإضافة في ﴿سوء العذاب﴾ تبين أنه أشد العذاب وأقبحه، ثم فصلت صورته بقتل الأبناء واستحياء النساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-894","number":894,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"لماذا قدّم ﴿يقتلون أبناءكم﴾ على ﴿ويستحيون نساءكم﴾؟","answer":"قدم قتل الأبناء لأنه أفجع وأشد إهلاكًا للجماعة، ثم ذكر إبقاء النساء للخدمة والاستذلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-895","number":895,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"ما سرّ التعبير هنا في قوله تعالى وفي مواضع ﴿يقتلون﴾، وفي البقرة ﴿يذبحون﴾؟","answer":"القتل أعم من الذبح ويصور إزهاق الأرواح، أما ﴿يذبحون﴾ فتفصل هيئة القتل البشعة؛ فكل موضع يبرز جهة من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-896","number":896,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"لماذا عُطف ﴿يقتلون﴾ بالواو هنا، وجُرّد ﴿يذبحون﴾ من العطف في البقرة 49؟","answer":"في الأعراف جُعل قتل الأبناء واستحياء النساء نوعين معطوفين من سوء العذاب؛ وفي البقرة جاءت ﴿يذبحون﴾ بيانًا وتفسيرًا لسوء العذاب، فناسب سقوط الواو.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-897","number":897,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"لماذا عبّر بالمضارع ﴿يقتلون... ويستحيون﴾ عن أحداث ماضية؟","answer":"المضارع يستحضر مشهد القتل والاستحياء ويصور تكرره واستمراره، حتى كأن العذاب يقع أمام السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-898","number":898,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"لماذا ختم بـ﴿وفي ذلكم بلاء من ربكم عظيم﴾؟","answer":"الإشارة في ﴿ذلكم﴾ إلى ما سبق من العذاب والإنجاء، و﴿البلاء﴾ يحتمل المحنة والاختبار والنعمة؛ وكل ذلك عظيم صادر من ربهم ليستوجب الاعتبار والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-899","number":899,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"إلى ماذا يشير ﴿ذلكم﴾: إلى العذاب أم إلى الإنجاء؟","answer":"يجوز أن تعود الإشارة إلى سوء العذاب المذكور، وأن تشمل مجموع ما سبق من العذاب والإنجاء؛ ففي العذاب محنة، وفي الإنجاء نعمة واختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-900","number":900,"surah":7,"verses":[141],"verseLabel":"الأعراف: 141","question":"لماذا وصف البلاء بأنه ﴿من ربكم﴾؟","answer":"إضافة البلاء إلى ﴿ربكم﴾ تذكر بأن ما جرى صادر عن تدبير المربي: ابتلى بالشدة وأنعم بالنجاة، ليستوجب الصبر والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص432–452.","url":""}]},{"id":"s7-901","number":901,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿وواعدنا موسى﴾ بصيغة المفاعلة مع أن ابتداء الوعد من الله؟","answer":"المواعدة تفيد أن الله وعد موسى الحضور والتكليم، وموسى قابل الوعد بالحضور والوفاء؛ فصيغت المفاعلة لاشتراك الطرفين في متعلق الموعد، وإن كان ابتداء الوعد من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-902","number":902,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير هنا في قوله تعالى ﴿واعدنا﴾، وفي البقرة ﴿وإذ واعدنا موسى أربعين ليلة﴾ ضمن سياق مختلف؟","answer":"في الأعراف فُصّل الموعد إلى ثلاثين ثم عشر وذُكرت خلافة هارون وما جرى عند الميقات؛ أما البقرة فورد في سياق تعداد النعم على بني إسرائيل فأجمل الأربعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-903","number":903,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"لماذا بدأ الموعد بـ﴿ثلاثين ليلة﴾ ثم قال: ﴿وأتممناها بعشر﴾ بدل أن يقول: أربعين ليلة؟","answer":"ذُكرت الثلاثون أولًا ثم الزيادة بالعشر لإظهار أن الموعد مر بمرحلتين، وأن العشر إتمام لما سبق، وفي ذلك تمهيد لما وقع في مدة غياب موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-904","number":904,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"لماذا عُبّر بالليالي لا بالأيام؟","answer":"عُبر بالليالي لأنها مبدأ حساب الشهور عند العرب، ولأن الخلوة والمناجاة ألصق بالليل؛ والمراد الليالي بأيامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-905","number":905,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿وأتممناها بعشر﴾ ولم يكرر «ليال»؟","answer":"حذف تمييز ﴿عشر﴾ لدلالة ﴿ثلاثين ليلة﴾ عليه، فاستغنى عن تكراره إيجازًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-906","number":906,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿فتم ميقات ربه أربعين ليلة﴾ بعد أن صار المجموع معلومًا؟","answer":"صرح بالمجموع توكيدًا لتمام الموعد ورفعًا لاحتمال أن تكون العشر داخلة في الثلاثين؛ فثبت أن الميقات أربعون ليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-907","number":907,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"لماذا أضاف الميقات إلى ﴿ربه﴾؟","answer":"إضافة الميقات إلى ﴿ربه﴾ تشريف له وبيان أن تحديده صادر عن الرب، وفي الإضافة معنى العناية بموسى وتربيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-908","number":908,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"لماذا عاد من ضمير التعظيم في ﴿واعدنا... أتممنا﴾ إلى الغيبة ﴿ربه﴾؟","answer":"الانتقال من التكلم في ﴿واعدنا﴾ إلى الاسم الظاهر ﴿ربه﴾ يبرز وصف الربوبية المناسب للتوقيت والتربية، مع التفات ينشط السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-909","number":909,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"ما دلالة طلب موسى من هارون: ﴿اخلفني في قومي﴾ مع أنه نبي؟","answer":"طلب منه أن يقوم مقامه في تدبير شؤون قومه مدة غيابه؛ فالخلافة هنا في سياسة القوم وحفظهم، ولا تنافي نبوة هارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-910","number":910,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿في قومي﴾ لا «على قومي»؟","answer":"﴿في قومي﴾ تجعل هارون قائمًا بينهم مباشرًا لأحوالهم، لا متسلطًا عليهم؛ فالمقام رعاية وإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-911","number":911,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"لماذا أمر هارون بـ﴿وأصلح﴾ مع صلاحه ونبوته؟","answer":"الأمر بالإصلاح طلب للاستمرار عليه وبذل الجهد في إصلاح ما قد يطرأ أثناء غيبة موسى، لا اتهام لهارون بالفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-912","number":912,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تتبع سبيل المفسدين﴾، دون أن يقال: ولا تفسد؟","answer":"النهي عن اتباع سبيل المفسدين أوسع من قول «لا تفسد»؛ فهو يمنع موافقتهم أو مداهنتهم أو سلوك أي طريق يوصل إلى فسادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-913","number":913,"surah":7,"verses":[142],"verseLabel":"الأعراف: 142","question":"لماذا أفرد ﴿سبيل﴾ وأضافه إلى جمع ﴿المفسدين﴾؟","answer":"أفرد ﴿سبيل﴾ لأن طرائق المفسدين، على تعددها، تجتمع في طريق واحد هو مخالفة أمر الله وإفساد الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-914","number":914,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما جاء موسى لميقاتنا﴾ مع أن الميقات زمن لا مكان؟","answer":"المجيء إلى الزمن مجاز عن بلوغه والحضور عند حلوله، كأن الميقات مقصد يؤتى؛ وقد اقترن الزمن بموضع المناجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-915","number":915,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا أضاف الميقات إلى الله: ﴿لميقاتنا﴾ بعد قوله ﴿ميقات ربه﴾؟","answer":"في ﴿ميقات ربه﴾ إبراز لعناية الرب بموسى، وفي ﴿لميقاتنا﴾ تشريف الموعد بإضافته إلى ضمير العظمة؛ فلكل إضافة مناسبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-916","number":916,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا عطف التكليم بقوله: ﴿وكلمه ربه﴾ بعد ذكر مجيئه للميقات؟","answer":"عطف التكليم لأنه الغاية التي جاء موسى للميقات من أجلها؛ فلما حضر وقع التكليم الإلهي بلا واسطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-917","number":917,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا أظهر ﴿ربه﴾ بدل الضمير: «وكلمناه»؟","answer":"إظهار ﴿ربه﴾ بدل «كلمناه» يستحضر وصف الربوبية والعناية في أشرف مقام، ويجعل المتكلم معلومًا على وجه التعظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-918","number":918,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"ما دلالة طلب موسى: ﴿رب أرني أنظر إليك﴾، فجمع بين الإراءة والنظر؟","answer":"﴿أرني﴾ طلب تهيئة الرؤية وإظهار الذات لموسى، و﴿أنظر إليك﴾ بيان للغاية المقصودة من الإراءة: حصول النظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-919","number":919,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا حذف ياء النداء فقال: ﴿رب﴾؟","answer":"حذف حرف النداء يدل على شدة القرب في المناجاة وسرعة التوجه، و﴿رب﴾ أنسب بالتضرع والافتقار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-920","number":920,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا أجابه الله بـ﴿لن تراني﴾ لا «لا تراني»؟","answer":"﴿لن﴾ تنفي حصول الرؤية في الحال الدنيوية التي عليها موسى نفيًا مؤكدًا، ولا تدل بذاتها على امتناع الرؤية أبدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-921","number":921,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا علق الرؤية على استقرار الجبل: ﴿فإن استقر مكانه فسوف تراني﴾؟","answer":"علقها بأمر ممكن في ذاته لكنه لا يقع عند التجلي؛ فلما عجز الجبل عن الثبات ظهر بطريق المشاهدة أن بنية موسى البشرية لا تحتملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-922","number":922,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا اختير الجبل مقياسًا لاحتمال التجلي؟","answer":"اختير الجبل لرسوخه وصلابته وعظم جرمه؛ فإذا لم يثبت هو للتجلي فالإنسان أضعف عن احتماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-923","number":923,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿فسوف تراني﴾ بسوف لا بالسين؟","answer":"﴿سوف﴾ تلائم التعليق على شرط منتظر الوقوع وتمنح زمنًا للنظر إلى نتيجة التجلي، بخلاف السين الأقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-924","number":924,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما تجلى ربه للجبل﴾، وعُدي التجلي باللام؟","answer":"التجلي الظهور والانكشاف، واللام في ﴿للجبل﴾ توجه التجلي إليه وتخصه به، فوقع أثره عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-925","number":925,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿جعله دكًا﴾ لا «فدكّه»؟","answer":"﴿جعله دكًا﴾ يدل على تحويل الجبل كله إلى هيئة الدك والتسوية، لا مجرد وقوع فعل الدق عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-926","number":926,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا نُكّر ﴿دكًا﴾؟","answer":"التنكير يصور دكًا عظيمًا هائلًا لا يحيط الوصف بمقداره؛ فصار الجبل مستويًا أو متفتتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-927","number":927,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿وخر موسى صعقًا﴾ لا «سقط»؟","answer":"الخرور سقوط سريع من علو من غير تماسك، فصور غلبة الصعق على موسى، وهو أبلغ تصويرًا من مطلق السقوط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-928","number":928,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا عبّر بـ﴿صعقًا﴾ بالمصدر؟","answer":"المصدر ﴿صعقًا﴾ وقع حالًا مبالغةً، أي خر مصعوقًا قد غشي عليه وذهب إدراكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-929","number":929,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما أفاق﴾ لا «فلما استيقظ»؟","answer":"الإفاقة رجوع العقل والحس بعد غشي أو صعق، أما الاستيقاظ فرجوع من النوم؛ فالإفاقة هي المطابقة لما أصابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-930","number":930,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا بدأ موسى بعد الإفاقة بالتسبيح: ﴿سبحانك﴾؟","answer":"بدأ بالتسبيح تنزيهًا لله عن أن تحيط به الأبصار، واعترافًا بعظمته بعد أن شاهد أثر التجلي في الجبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-931","number":931,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿تبت إليك﴾، وممَّ تاب موسى؟","answer":"تاب من الإقدام على سؤال الرؤية في الدنيا قبل الإذن، ورجع إلى الوقوف عند ما بينه الله له، لا من شك في ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-932","number":932,"surah":7,"verses":[143],"verseLabel":"الأعراف: 143","question":"لماذا ختم بقوله: ﴿وأنا أول المؤمنين﴾؟","answer":"أي أنا أول المؤمنين من قومي بأنك لا تُرى في هذه الحال، أو أول المسارعين إلى الإيمان بما ظهر لي؛ فختم الموقف بالتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص453–490.","url":""}]},{"id":"s7-933","number":933,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"لماذا خاطبه الله باسمه: ﴿يا موسى﴾ بعد الصعق والإفاقة؟","answer":"النداء باسمه تلطف وتشريف بعد الإفاقة، ورد له من هول الصعق إلى خطاب الاصطفاء والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-934","number":934,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"لماذا أكد الخبر بـ﴿إني اصطفيتك﴾؟","answer":"أكد الخبر بـ﴿إن﴾ لأن المقام عقب طلب لم يتحقق، فدفع ما قد يجده موسى من أسف وقرر له عظيم ما اختصه الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-935","number":935,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿اصطفيتك﴾ لا «اخترتك»؟","answer":"الاصطفاء اختيار مع تنقية وتفضيل، فهو أخص من مطلق الاختيار، ويلائم الرسالة والتكليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-936","number":936,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"لماذا عُدّي الاصطفاء بـ﴿على الناس﴾؟","answer":"﴿على الناس﴾ تبين رفعة منزلته بينهم بما خص به، فالاصطفاء تفضيل لا مجرد اختيار لمهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-937","number":937,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"هل المراد بـ﴿على الناس﴾ جميع البشر أم أهل زمان موسى؟","answer":"المراد ناس زمانه، أو من أرسل إليهم، لا جميع البشر إلى قيام الساعة؛ فقد ثبت تفضيل غيره من الأنبياء في وجوه أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-938","number":938,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"لماذا جمع ﴿برسالاتي﴾ وأفرد ﴿وبكلامي﴾؟","answer":"جُمعت الرسالات لتعدد ما أُرسل به من أوامر ونواه وألواح، وأُفرد الكلام لأنه مصدر يدل على الجنس، أو للخصوصية الواحدة وهي التكليم بلا واسطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-939","number":939,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"لماذا قدّم ﴿برسالاتي﴾ على ﴿بكلامي﴾؟","answer":"قُدمت الرسالات لأنها المقصود المتعدي إلى الأمة ووظيفة موسى الكبرى، ثم ذكر الكلام تشريفًا خاصًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-940","number":940,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"لماذا أضاف الرسالات والكلام إلى الله؟","answer":"الإضافة تشريف وتوثيق للمصدر: الرسالات صادرة من الله والكلام كلامه حقيقة، لا من صنع بشر أو واسطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-941","number":941,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"لماذا فرّع على الاصطفاء قوله: ﴿فخذ ما آتيتك﴾؟","answer":"الفاء تجعل أخذ العطاء والشكر نتيجة عملية للاصطفاء؛ فمن اختير للرسالة لزمه قبولها والقيام بحقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-942","number":942,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿ما آتيتك﴾ ولم يحدد المأخوذ؟","answer":"﴿ما آتيتك﴾ تعم ما وهبه الله من الرسالات والكلام والألواح وسائر النعم، فلم تقيده بشيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-943","number":943,"surah":7,"verses":[144],"verseLabel":"الأعراف: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿وكن من الشاكرين﴾ لا «واشكر»؟","answer":"﴿كن من الشاكرين﴾ تطلب ثباته في جماعة المتصفين بالشكر ودوام الصفة، لا فعل شكر عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–503.","url":""}]},{"id":"s7-944","number":944,"surah":7,"verses":[144,145],"verseLabel":"الأعراف: 144–145","question":"ما سرّ ذكر القوة في قوله تعالى: ﴿فخذها بقوة﴾، وعدم ذكرها قبلها في ﴿فخذ ما آتيتك﴾؟","answer":"الأولى إجمال في الأخذ وجاءت عقب الإفاقة من الصعق؛ والثانية في الألواح المفصلة وتبليغ القوم والعمل بها، وذلك يحتاج إلى قوة وعزيمة. فناسب الإجمالُ الإجمالَ والتفصيلُ التفصيلَ.","sources":[{"label":"فاضل السامرائي، [«التفريق بين الأمر بالأخذ في آيتي سورة الأعراف: فخذ ما آتيتك وفخذها بقوة»](https://islamsyria.com/articles/%D8%A7%D9%84%D8%AA%D9%81%D8%B1%D9%8A%D9%82-%D8%A8%D9%8A%D9%86-%D8%A7%D9%84%D8%A3%D9%85%D8%B1-%D8%A8%D8%A7%D9%84%D8%A3%D8%AE%D8%B0-%D9%81%D9%8A-%D8%A2%D9%8A%D8%AA%D9%8A-%D8%B3%D9%88%D8%B1%D8%A9-%D8%A7%D9%84%D8%A3%D8%B9%D8%B1%D8%A7%D9%81-%D9%81%D8%AE%D8%B0-%D9%85%D8%A7-%D8%A2%D8%AA%D9%8A%D8%AA%D9%83-%D9%88-%D9%81%D8%AE%D8%B0%D9%87%D8%A7-%D8%A8%D9%82%D9%88%D8%A9)، رابطة العلماء السوريين.","url":""}]},{"id":"s7-945","number":945,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وكتبنا له في الألواح﴾ بضمير الغيبة بعد خطاب موسى مباشرة؟","answer":"الالتفات إلى الغيبة ينقل من خطاب الاصطفاء إلى حكاية ما أنعم الله به على موسى للأمة، ويتيح وصف العطاء في سياق خبري.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-946","number":946,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"لماذا عُدّيت الكتابة بـ﴿في الألواح﴾ لا «على الألواح»؟","answer":"﴿في الألواح﴾ تفيد أن الكتابة مثبتة مستقرة في مادتها، كأن المعاني مودعة فيها، وهي أبلغ من مجرد الاستعلاء السطحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-947","number":947,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"لماذا جُمعت ﴿الألواح﴾ ولم يُذكر عددها أو مادتها؟","answer":"الجمع يدل على تعدد الألواح، وأغفل العدد والمادة لأن العبرة بما كتب فيها لا بهيئتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-948","number":948,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿من كل شيء﴾ مع أن الألواح لم تشمل كل معلومات الوجود؟","answer":"﴿من كل شيء﴾ أي من كل ما يحتاج إليه بنو إسرائيل في دينهم وشريعتهم، لا كل معلومات الوجود؛ فالعموم مقيد بالمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-949","number":949,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"لماذا نُصبت ﴿موعظة وتفصيلًا﴾ بعد ﴿من كل شيء﴾؟","answer":"هما منصوبان على الحال من المكتوب، أو مفعول لأجله/بدل بحسب الإعراب؛ والمعنى أن المكتوب جاء موعظة وتفصيلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-950","number":950,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"ما سرّ تقديم ﴿موعظة﴾ على ﴿تفصيلًا﴾؟","answer":"قُدمت الموعظة لأنها تصلح القلب وتحمله على القبول، ثم يأتي التفصيل الذي يبين الأحكام والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-951","number":951,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"لماذا كرر ﴿كل شيء﴾ في الآية نفسها؟","answer":"الأولى تعم أنواع ما يحتاجون إليه من المكتوبات، والثانية تؤكد تفصيل كل أمر من تلك الأمور وبيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-952","number":952,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿فخذها بقوة﴾، وما القوة المطلوبة في أخذ الألواح؟","answer":"الأخذ بقوة هو الجد والعزم في الحفظ والفهم والعمل والتبليغ، لا مجرد حمل الألواح باليد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-953","number":953,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"لماذا انتقل من خطاب موسى إلى قومه: ﴿وأمر قومك يأخذوا بأحسنها﴾؟","answer":"لم يكن العطاء لموسى وحده؛ فانتقل الخطاب من تكليفه بالأخذ إلى تكليفه بتبليغ قومه وحملهم على العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-954","number":954,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"لماذا حُذفت الباء أو «أن» قبل ﴿يأخذوا﴾؟","answer":"﴿يأخذوا﴾ جواب للأمر ﴿وأمر﴾، أو على تقدير «أن يأخذوا» فحذف حرف المصدر؛ والإيجاز يجعل الأخذ كأنه الأثر المباشر للأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-955","number":955,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"كيف يُفهم قوله تعالى: ﴿يأخذوا بأحسنها﴾، وهل في الألواح ما ليس حسنًا؟","answer":"ليس في الألواح قبيح؛ والأحسن قد يعني الواجب والعزيمة في مقابل المباح والرخصة، أو الأخذ بما هو أحسن تطبيقًا من بين وجوه الحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-956","number":956,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿سأريكم دار الفاسقين﴾؟","answer":"الوعيد يجعل مصير الفاسقين منظورًا كأنه دار تُرى، ليعتبروا بعاقبة من خرج عن أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-957","number":957,"surah":7,"verses":[145],"verseLabel":"الأعراف: 145","question":"ما المراد بـ﴿دار الفاسقين﴾: مصر أم مساكن الهالكين أم جهنم؟","answer":"تشمل مساكن الأمم الهالكة التي سيرونها، وقيل مصر، وقيل جهنم؛ والسياق يحتمل العبرة بمصير الفاسقين في الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص504–520.","url":""}]},{"id":"s7-958","number":958,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿سأصرف عن آياتي﴾، وما معنى صرف المتكبرين عنها؟","answer":"الصرف مجازاة لهم على الاستكبار: يحرمون فهم الآيات والاعتبار بها، أو يصرفون عن إبطالها، لا أنهم يمنعون قسرًا من إيمان أرادوه بإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-959","number":959,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"لماذا أضاف الآيات إلى الله: ﴿عن آياتي﴾؟","answer":"إضافتها إلى الله تشرف الآيات وتعظم جريمة الإعراض عنها؛ فهي دلائله ووحيه وليست كلامًا بشريًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-960","number":960,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"لماذا وُصفوا بـ﴿الذين يتكبرون﴾ بالمضارع؟","answer":"المضارع في ﴿يتكبرون﴾ يصور تجدد تكبرهم واستمراره حتى صار دأبًا يصدهم عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-961","number":961,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"لماذا قُيّد تكبرهم بـ﴿في الأرض﴾؟","answer":"﴿في الأرض﴾ يفضح تكبر المخلوق في موطن عبوديته، ويوسع أثر فسادهم بين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-962","number":962,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿بغير الحق﴾، وهل يكون التكبر بحق؟","answer":"القيد كاشف لواقع تكبرهم؛ فالكبرياء الحق لله وحده، ولا يكون تكبر البشر بحق. وقيل للاحتراز من إظهار العزة على أهل الباطل دون بطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-963","number":963,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"لماذا كرر الشرط: ﴿وإن يروا كل آية... وإن يروا سبيل الرشد... وإن يروا سبيل الغي﴾؟","answer":"تكرار الشرط يفصل وجوه عنادهم: لا يؤمنون بالدليل مهما ظهر، ويرفضون طريق الرشد، ويتخذون طريق الغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-964","number":964,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿كل آية﴾ بالإفراد بعد ﴿كل﴾؟","answer":"جاء المفرد بعد ﴿كل﴾ لأن ﴿كل﴾ تستغرق أفراد الجنس واحدًا واحدًا؛ أي مهما يروا آية من الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-965","number":965,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يؤمنوا بها﴾، دون أن يقال: يكذبوا بها؟","answer":"نفي الإيمان يتناول رفض التصديق والانقياد معًا، فهو أوسع من مجرد وصفهم بالتكذيب اللفظي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-966","number":966,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"لماذا قوبل ﴿سبيل الرشد﴾ بـ﴿سبيل الغي﴾؟","answer":"الرشد إصابة طريق الحق والصلاح، والغي العدول عنه إلى الفساد؛ فهما طريقان متقابلان في الوجهة والعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-967","number":967,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى في الطريقين: ﴿لا يتخذوه سبيلًا﴾ و﴿يتخذوه سبيلًا﴾؟","answer":"الاتخاذ فعل قصد واختيار؛ فهم لا يكتفون بترك الرشد بل يرفضون جعله طريقًا، ويعمدون إلى الغي فيجعلونه طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-968","number":968,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"لماذا أعيد لفظ ﴿سبيلًا﴾ بعد ﴿سبيل الرشد﴾ و﴿سبيل الغي﴾؟","answer":"أعيد ﴿سبيلًا﴾ لتأكيد أن موقفهم ليس رؤية عابرة للطريقين، بل اتخاذ أحدهما منهجًا ورفض الآخر منهجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-969","number":969,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك بأنهم كذبوا بآياتنا وكانوا عنها غافلين﴾؟","answer":"اسم الإشارة يلخص سبب الصرف واتخاذ الغي: تكذيبهم بآيات الله وإعراضهم عن تدبرها والعمل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-970","number":970,"surah":7,"verses":[146],"verseLabel":"الأعراف: 146","question":"لماذا جُمِع بين التكذيب والغفلة مرة أخرى بعد الآية 136؟","answer":"في الآية 136 وصف حال فرعون وقومه قبل الإغراق، وهنا وصف سنة المتكبرين وعلة صرفهم عن الآيات؛ فتكرر الوصف لاتحاد أصل الداء مع اختلاف المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص521–536.","url":""}]},{"id":"s7-971","number":971,"surah":7,"verses":[147],"verseLabel":"الأعراف: 147","question":"لماذا أعيد الموصول: ﴿والذين كذبوا بآياتنا ولقاء الآخرة﴾؟","answer":"أعيد الموصول لاستئناف حكم مخصوص بمن جمعوا تكذيب الآيات وإنكار الآخرة، وتمييزهم من المتكبرين المذكورين قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص537–543.","url":""}]},{"id":"s7-972","number":972,"surah":7,"verses":[147],"verseLabel":"الأعراف: 147","question":"لماذا عُطف ﴿لقاء الآخرة﴾ على ﴿آياتنا﴾؟","answer":"عطف لقاء الآخرة لأن إنكار الجزاء أصل مستقل يفسد العمل، كما يفسده تكذيب الوحي والدلائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص537–543.","url":""}]},{"id":"s7-973","number":973,"surah":7,"verses":[147],"verseLabel":"الأعراف: 147","question":"ما سرّ التعبير بقوله تعالى: ﴿لقاء الآخرة﴾ لا «لقاء الله»؟","answer":"﴿لقاء الآخرة﴾ يعم لقاء ما في الدار الآخرة من بعث وحساب وجزاء، فيناسب مقام حبوط الأعمال والجزاء عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص537–543.","url":""}]},{"id":"s7-974","number":974,"surah":7,"verses":[147],"verseLabel":"الأعراف: 147","question":"ما سرّ التعبير في قوله تعالى: ﴿حبطت أعمالهم﴾، وصوّر الأعمال كشيء يفسد؟","answer":"الحبوط أصله فساد العمل أو بطن الدابة من أكل ضار؛ فصور الأعمال التي ظنوها نافعة وقد فسدت وضاع ثوابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص537–543.","url":""}]},{"id":"s7-975","number":975,"surah":7,"verses":[147],"verseLabel":"الأعراف: 147","question":"لماذا جاء ﴿حبطت﴾ بالماضي؟","answer":"الماضي يقرر تحقق الحبوط وثبوته بسبب الكفر، حتى كأنه أمر وقع وانتهى لا ينتظر حكمًا مستقبلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص537–543.","url":""}]},{"id":"s7-976","number":976,"surah":7,"verses":[147],"verseLabel":"الأعراف: 147","question":"لماذا ختم باستفهام: ﴿هل يجزون إلا ما كانوا يعملون﴾؟","answer":"الاستفهام إنكاري تقريري يفيد عدل الجزاء وحصره: لا يجزون إلا جنس ما داوموا على عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص537–543.","url":""}]},{"id":"s7-977","number":977,"surah":7,"verses":[147],"verseLabel":"الأعراف: 147","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كانوا يعملون﴾ لا «ما عملوا»؟","answer":"﴿كانوا يعملون﴾ تدل على الاستمرار والعادة، فجزاءهم على منهج لازم لا على زلة منفردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص537–543.","url":""}]},{"id":"s7-978","number":978,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿واتخذ قوم موسى من بعده﴾، دون أن يقال: بنو إسرائيل؟","answer":"إضافتهم إلى موسى تستحضر قبح انقلاب قوم نبيهم في غيبته، وتبرئ موسى من فعلهم؛ وهي أنسب من الاسم النسبي المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-979","number":979,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعده﴾ مع أن غيبة موسى معلومة؟","answer":"﴿من بعده﴾ أي بعد ذهابه إلى الميقات، وفيها تصوير سرعة الفتنة فور غيابه، لا بعد وفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-980","number":980,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿من حليهم﴾، وما دلالة نسبة الحلي إليهم؟","answer":"نسب الحلي إليهم لأنها صارت في أيديهم وحيازتهم، وإن كان أصلها مما استعاروه من القبط؛ ومنها صيغ العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-981","number":981,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"لماذا نُكّر ﴿عجلًا﴾ ثم وُصف بـ﴿جسدًا﴾؟","answer":"نُكر ﴿عجلًا﴾ للتحقير أو لأنه عجل غير معهود، ثم كشفت ﴿جسدًا﴾ أنه مجرد جثة بلا روح.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-982","number":982,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿عجلًا جسدًا﴾ لا «تمثال عجل»؟","answer":"﴿عجلًا جسدًا﴾ يوهم أولًا صورة الحيوان ثم يبطلها بوصف الجسد؛ فهو جسم على هيئة عجل لا كائن حي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-983","number":983,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير بقوله تعالى: ﴿له خوار﴾ مع أنه جسد مصنوع؟","answer":"كان يصدر منه صوت كخوار العجل، إما بسبب مرور الهواء في صنعته؛ فذكر الخوار لأنه موضع افتتانهم مع بقاء الجسد عاجزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-984","number":984,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"لماذا احتج عليهم بقوله: ﴿ألم يروا أنه لا يكلمهم﴾؟","answer":"الكلام من أوضح دلائل العلم والإرادة، فإذا كان لا يجيب عابديه ظهر بطلان ألوهيته مما يشاهدونه بأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-985","number":985,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"ما سرّ تقديم نفي الكلام على نفي الهداية؟","answer":"قدم نفي الكلام لأنه يتعلق مباشرة بدعائهم وعبادتهم: لا يجيبهم، ثم عمم عجزه بأنه لا يرشدهم إلى أي سبيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-986","number":986,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يهديهم سبيلًا﴾ لا «ولا يهديهم» فقط؟","answer":"ذكر ﴿سبيلًا﴾ لتعمية النفي: لا يدلهم على طريق واحد من طرق الخير، فضلًا عن طريق النجاة والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-987","number":987,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"لماذا كرر ﴿اتخذوه﴾ بعد تفصيل صنعه وعجزه؟","answer":"أعيد ﴿اتخذوه﴾ بعد إظهار عجزه للتعجيب والتوبيخ: مع وضوح أنه جسد لا يكلم ولا يهدي، اتخذوه إلهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-988","number":988,"surah":7,"verses":[148],"verseLabel":"الأعراف: 148","question":"لماذا ختم بـ﴿وكانوا ظالمين﴾؟","answer":"الخاتمة تبين أن فعلهم ناشئ عن ظلم راسخ: ظلموا أنفسهم بالشرك ووضعوا العبادة في غير موضعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص544–558.","url":""}]},{"id":"s7-989","number":989,"surah":7,"verses":[149],"verseLabel":"الأعراف: 149","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما سقط في أيديهم﴾، وما صورة السقوط في اليد؟","answer":"هذا مثل للندم الشديد والحيرة؛ كأن الندم وقع في أيديهم أو عضوا أيديهم بعد فوات الأمر، فصاروا عاجزين متحسرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص559–572.","url":""}]},{"id":"s7-990","number":990,"surah":7,"verses":[149],"verseLabel":"الأعراف: 149","question":"لماذا بُني ﴿سقط﴾ للمجهول ولم يذكر الساقط؟","answer":"جاء التعبير على البناء للمجهول لأنه مثل ثابت لا يقصد فيه تعيين ساقط، ولأن المهم حلول الندم بهم بغتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص559–572.","url":""}]},{"id":"s7-991","number":991,"surah":7,"verses":[149],"verseLabel":"الأعراف: 149","question":"لماذا جمع بين ﴿سقط في أيديهم﴾ و﴿ورأوا أنهم قد ضلوا﴾؟","answer":"الأول يصور حال الندم والحسرة، والثاني يبين سببها العقلي: تبين لهم أنهم فارقوا طريق الحق؛ فجمع الشعور وإدراك الخطأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص559–572.","url":""}]},{"id":"s7-992","number":992,"surah":7,"verses":[149],"verseLabel":"الأعراف: 149","question":"لماذا أكد ضلالهم بـ﴿أنهم قد ضلوا﴾؟","answer":"﴿أن﴾ و﴿قد﴾ تثبتان تحقق الضلال ووضوحه لهم بعد انكشاف الفتنة؛ فلم يعد مجرد ظن.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص559–572.","url":""}]},{"id":"s7-993","number":993,"surah":7,"verses":[149],"verseLabel":"الأعراف: 149","question":"ما سرّ تقديم الرحمة على المغفرة في قولهم: ﴿لئن لم يرحمنا ربنا ويغفر لنا﴾؟","answer":"قدّموا الرحمة لأنها الأصل الواسع الذي يتفضل الله به، ومنها تنشأ المغفرة ومحو الذنب؛ أو لأن حاجتهم إلى قبول التوبة قبل ستر الخطيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص559–572.","url":""}]},{"id":"s7-994","number":994,"surah":7,"verses":[149],"verseLabel":"الأعراف: 149","question":"ما دلالة قولهم: ﴿ربنا﴾ بعد عبادتهم العجل؟","answer":"قولهم ﴿ربنا﴾ اعتراف بالرجوع إلى ربهم الحق بعد بطلان العجل، واستعطاف بوصف الربوبية والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص559–572.","url":""}]},{"id":"s7-995","number":995,"surah":7,"verses":[149],"verseLabel":"الأعراف: 149","question":"لماذا أكدوا الخسران باللام والنون: ﴿لنكونن من الخاسرين﴾؟","answer":"اللام ونون التوكيد تثبتان يقينهم بأن عدم الرحمة والمغفرة يوقعهم حتمًا في الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص559–572.","url":""}]},{"id":"s7-996","number":996,"surah":7,"verses":[149],"verseLabel":"الأعراف: 149","question":"ما سرّ تعبيرهم: ﴿من الخاسرين﴾ لا «خاسرين»؟","answer":"﴿من الخاسرين﴾ تدخلهم في زمرة معروفة استقر فيها الخسران، فهي أبلغ من وصفهم بخسارة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص559–572.","url":""}]},{"id":"s7-997","number":997,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما رجع موسى إلى قومه غضبان أسفًا﴾، فجمع الغضب والأسف؟","answer":"الغضب إنكار شديد لما وقع من الشرك، والأسف شدة الحزن والتلهف عليه؛ فجمع بين الغيرة للحق والألم على ضلال قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-998","number":998,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"ما سرّ تقديم ﴿غضبان﴾ على ﴿أسفًا﴾؟","answer":"قُدم الغضب لأنه الحال الظاهرة الدافعة إلى المواجهة، ثم أتبعه الأسف وهو شدة الحزن الباطن على ما وقع منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-999","number":999,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿بئسما خلفتموني من بعدي﴾؟","answer":"﴿بئسما﴾ ذم شديد لما صنعوه في غيبته، و﴿خلفتموني﴾ أي بئس الخلافة التي قمتم بها بعدي إذ عبدتم العجل وخالفتم وصيتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1000","number":1000,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"لماذا جمع بين ﴿خلفتموني﴾ و﴿من بعدي﴾؟","answer":"﴿خلفتموني﴾ تبين أنهم صاروا خلفاءه في القوم، و﴿من بعدي﴾ تؤكد أن الفساد وقع عقب غيبته مباشرة؛ فالجمع للتوكيد وتصوير سرعة الانقلاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1001","number":1001,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"لماذا سألهم: ﴿أعجلتم أمر ربكم﴾؟","answer":"الاستفهام إنكاري: أعجلتم عن أمر ربكم وميعاده قبل تمامه، واستبقتم حكمه فاتخذتم العجل؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1002","number":1002,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"لماذا أضاف الأمر إلى ﴿ربكم﴾؟","answer":"إضافة الأمر إلى الرب تعظم ما استعجلوه وخالفوه، وتذكرهم بأن الميقات والتشريع صادران ممن يربيهم وينعم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1003","number":1003,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"لماذا ألقى موسى الألواح مع أنه أُمر أن يأخذها بقوة؟","answer":"ألقى الألواح من شدة الغضب لله عند رؤية الشرك، إلقاءً عارضًا لا رفضًا لها؛ ثم عاد فأخذها، فلا يناقض الأمر بأخذها بقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1004","number":1004,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿وأخذ برأس أخيه يجره إليه﴾ لا «عاتب أخاه»؟","answer":"حكى الفعل المحسوس شدة غضبه وعتابه لهارون، إذ أخذ بشعر رأسه يجره إليه ظانًا أنه قصر، وهو أبلغ في تصوير المشهد من لفظ العتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1005","number":1005,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"لماذا نادى هارون موسى بقوله: ﴿ابن أم﴾ لا «يا أخي»؟","answer":"استعطفه برابطة الأم لأنها أرق وأدعى للرحمة، وهما أخوان لأب وأم؛ فاختار النداء الذي يهدئ غضبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1006","number":1006,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"ما دلالة اعتذار هارون: ﴿إن القوم استضعفوني﴾؟","answer":"بيّن أنه لم يرض بعبادة العجل، لكن القوم عدوه ضعيفًا ولم يطيعوه، فكان قوله دفعًا لتهمة التقصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1007","number":1007,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"لماذا جمع بين ﴿استضعفوني﴾ و﴿كادوا يقتلونني﴾؟","answer":"﴿استضعفوني﴾ يبين بداية تسلطهم ورفضهم أمره، و﴿كادوا يقتلونني﴾ يبلغ بهذا التسلط غايته؛ فالعجز كان عن مقاومة فتنة تهدد حياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1008","number":1008,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تشمت بي الأعداء﴾ قبل قوله ﴿ولا تجعلني مع القوم الظالمين﴾؟","answer":"بدأ بطلب ألا يجعل عتابه سببًا لفرح أهل العداوة، ثم طلب ألا يحكم عليه مع الظالمين؛ فانتقل من أثر الموقف الظاهر إلى براءته من فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1009","number":1009,"surah":7,"verses":[150],"verseLabel":"الأعراف: 150","question":"لماذا سمّى بعض القوم ﴿الأعداء﴾ مع أنهم من بني إسرائيل؟","answer":"سموا أعداء لأنهم عاندوا التوحيد وفرحوا بما يصيب هارون، وإن جمعهم نسب واحد؛ فالعداوة هنا دينية وموقفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص573–593.","url":""}]},{"id":"s7-1010","number":1010,"surah":7,"verses":[151],"verseLabel":"الأعراف: 151","question":"لماذا بدأ موسى بالدعاء: ﴿رب اغفر لي ولأخي﴾ بعد سماع عذر هارون؟","answer":"لما تبين له عذر أخيه رجع إلى ربه، فاستغفر لنفسه من العجلة في مؤاخذته، ولأخيه مما قد يكون من تقصير لا يعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص594–597.","url":""}]},{"id":"s7-1011","number":1011,"surah":7,"verses":[151],"verseLabel":"الأعراف: 151","question":"لماذا قدّم نفسه في المغفرة: ﴿لي ولأخي﴾؟","answer":"قدم نفسه لأنه بدأ بالاعتراف بما صدر منه من العجلة، ولأن الداعي يبدأ بنفسه، ثم ضم أخاه إليه إظهارًا لوحدة موقفهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص594–597.","url":""}]},{"id":"s7-1012","number":1012,"surah":7,"verses":[151],"verseLabel":"الأعراف: 151","question":"لماذا طلب المغفرة لهارون مع ظهور عذره؟","answer":"الاستغفار لا يقتضي ثبوت ذنب محقق؛ هو دعاء بالستر والتجاوز عما قد يكون وقع من قصور في مقاومة القوم، وزيادة في التواضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص594–597.","url":""}]},{"id":"s7-1013","number":1013,"surah":7,"verses":[151],"verseLabel":"الأعراف: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿وأدخلنا في رحمتك﴾، فصوّر الرحمة مكانًا يُدخل فيه؟","answer":"صورت الرحمة كحيز واسع يحيط بهما ويحميهما، فطلبا رحمة شاملة لا عطاءً جزئيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص594–597.","url":""}]},{"id":"s7-1014","number":1014,"surah":7,"verses":[151],"verseLabel":"الأعراف: 151","question":"لماذا ختم بـ﴿وأنت أرحم الراحمين﴾؟","answer":"ختم بأوسع وصف للرحمة توسلًا يناسب قوله ﴿وأدخلنا في رحمتك﴾، وإقرارًا بأن رحمته فوق رحمة كل راحم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص594–597.","url":""}]},{"id":"s7-1015","number":1015,"surah":7,"verses":[152],"verseLabel":"الأعراف: 152","question":"لماذا أعيد وصفهم بـ﴿الذين اتخذوا العجل﴾ بدل الضمير؟","answer":"أظهر الموصول ليعيد وصف جرمهم نفسه في مقام الوعيد، فيكون سبب العقوبة حاضرًا: اتخاذ العجل إلهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص598–606.","url":""}]},{"id":"s7-1016","number":1016,"surah":7,"verses":[152],"verseLabel":"الأعراف: 152","question":"لماذا حُذف المفعول الثاني لـ﴿اتخذوا العجل﴾؟","answer":"حذف المفعول الثاني، أي «إلهًا»، للعلم به من السياق، وللاستهجان حتى كأن ذكره مما ينزه عنه اللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص598–606.","url":""}]},{"id":"s7-1017","number":1017,"surah":7,"verses":[152],"verseLabel":"الأعراف: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿سينالهم غضب﴾، فجعل الغضب نائلًا لهم؟","answer":"جعل الغضب والذلة كأنهما طالبان يدركانهم حتمًا؛ وفي ﴿سينالهم﴾ وعيد قريب الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص598–606.","url":""}]},{"id":"s7-1018","number":1018,"surah":7,"verses":[152],"verseLabel":"الأعراف: 152","question":"لماذا نُكّر ﴿غضب﴾ و﴿ذلة﴾؟","answer":"التنكير للتهويل: غضب عظيم وذلة عظيمة لا يحيط السامع بمقدارهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص598–606.","url":""}]},{"id":"s7-1019","number":1019,"surah":7,"verses":[152],"verseLabel":"الأعراف: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿من ربهم﴾ مع نزول الغضب؟","answer":"حتى الغضب نُسب إلى ﴿ربهم﴾؛ لأن العقوبة صادرة عن رب عادل أقام عليهم الحجة ورباهم بالنعم، فكان جرمهم أقبح.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص598–606.","url":""}]},{"id":"s7-1020","number":1020,"surah":7,"verses":[152],"verseLabel":"الأعراف: 152","question":"لماذا قيّد الذلة بـ﴿في الحياة الدنيا﴾؟","answer":"قيدها بالدنيا لبيان أن أثر الشرك لا ينتظر الآخرة، بل يلحقهم فيه هوان دنيوي، مع بقاء عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص598–606.","url":""}]},{"id":"s7-1021","number":1021,"surah":7,"verses":[152],"verseLabel":"الأعراف: 152","question":"لماذا سمّى عبادة العجل افتراءً: ﴿وكذلك نجزي المفترين﴾؟","answer":"لأنهم اختلقوا على الله شريكًا ونسبوا الألوهية إلى العجل بلا برهان؛ فهذا أظهر الافتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص598–606.","url":""}]},{"id":"s7-1022","number":1022,"surah":7,"verses":[152],"verseLabel":"الأعراف: 152","question":"لماذا انتقل من الغيبة إلى ضمير التعظيم في ﴿نجزي﴾؟","answer":"الالتفات إلى ﴿نجزي﴾ يواجههم بسلطان المجازاة ويعمم الحكم من قصتهم إلى سنة إلهية في كل مفتر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص598–606.","url":""}]},{"id":"s7-1023","number":1023,"surah":7,"verses":[153],"verseLabel":"الأعراف: 153","question":"لماذا قابل وعيد المفترين بقوله: ﴿والذين عملوا السيئات ثم تابوا﴾؟","answer":"بعد الوعيد فتح باب الرجاء: حتى من عمل السيئات إذا تاب وآمن وجد المغفرة والرحمة، فلا يتحول الوعيد إلى يأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص607–612.","url":""}]},{"id":"s7-1024","number":1024,"surah":7,"verses":[153],"verseLabel":"الأعراف: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿عملوا السيئات﴾ لا «أساؤوا»؟","answer":"ذكر العمل يثبت أن السيئات أفعال اكتسبوها وداوموا عليها، لا مجرد وصف عابر، ومع ذلك تقبل التوبة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص607–612.","url":""}]},{"id":"s7-1025","number":1025,"surah":7,"verses":[153],"verseLabel":"الأعراف: 153","question":"لماذا جمع ﴿السيئات﴾؟","answer":"الجمع يشمل كثرة الذنوب وتنوعها، وفيه توسيع لباب التوبة مهما تعددت السيئات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص607–612.","url":""}]},{"id":"s7-1026","number":1026,"surah":7,"verses":[153],"verseLabel":"الأعراف: 153","question":"لماذا عطف التوبة بـ﴿ثم﴾؟","answer":"﴿ثم﴾ تفيد التراخي الرتبي أو الزمني؛ فالتوبة نقلة عظيمة بعد التوغل في السيئات، وقد تأتي بعد مدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص607–612.","url":""}]},{"id":"s7-1027","number":1027,"surah":7,"verses":[153],"verseLabel":"الأعراف: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعدها﴾ بالإفراد مع جمع السيئات؟","answer":"عاد الضمير مفردًا إلى العمل المفهوم من ﴿عملوا﴾، أو إلى السيئات باعتبار جنسها ومجموعها كشيء واحد؛ أي من بعد عملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص607–612.","url":""}]},{"id":"s7-1028","number":1028,"surah":7,"verses":[153],"verseLabel":"الأعراف: 153","question":"لماذا أكد المغفرة بـ﴿إن ربك من بعدها لغفور رحيم﴾؟","answer":"أكدت الجملة بـ﴿إن﴾ واللام لرفع اليأس بعد عظم السيئات، وتثبيت أن المغفرة والرحمة حاصلتان لمن صدق في التوبة والإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص607–612.","url":""}]},{"id":"s7-1029","number":1029,"surah":7,"verses":[153],"verseLabel":"الأعراف: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿ربك﴾ خطابًا للنبي محمد ﷺ في سياق قصة موسى؟","answer":"الخطاب للنبي ﷺ يربط العبرة من قصة موسى برسالته، ويواسيه بأن ربه يغفر للتائبين من أمته كما فتح الباب لمن سبق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص607–612.","url":""}]},{"id":"s7-1030","number":1030,"surah":7,"verses":[153],"verseLabel":"الأعراف: 153","question":"لماذا جُمع بين ﴿غفور رحيم﴾؟","answer":"﴿غفور﴾ لمحو الذنب وستره، و﴿رحيم﴾ لإيصال الخير بعد المغفرة؛ فالتائب لا ينجو فقط بل تناله الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص607–612.","url":""}]},{"id":"s7-1031","number":1031,"surah":7,"verses":[154],"verseLabel":"الأعراف: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما سكت عن موسى الغضب﴾، فجعل الغضب كأنه متكلم؟","answer":"شبه الغضب بشخص كان يحرك موسى ويدفعه إلى الكلام والفعل ثم سكت عنه؛ فصوّر هدوء ثورته بعد زوال سببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص613–620.","url":""}]},{"id":"s7-1032","number":1032,"surah":7,"verses":[154],"verseLabel":"الأعراف: 154","question":"لماذا عُدّي السكوت بـ﴿عن﴾؟","answer":"﴿سكت عن موسى﴾ تفيد انصراف سلطان الغضب عنه وكف أثره، كما يكف المتكلم كلامه عن شخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص613–620.","url":""}]},{"id":"s7-1033","number":1033,"surah":7,"verses":[154],"verseLabel":"الأعراف: 154","question":"لماذا أعاد موسى أخذ الألواح بعد أن ألقاها؟","answer":"لما هدأ غضبه عاد إلى الألواح تعظيمًا للوحي وامتثالًا للأخذ بها؛ فإلقاؤها كان حالًا عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص613–620.","url":""}]},{"id":"s7-1034","number":1034,"surah":7,"verses":[154],"verseLabel":"الأعراف: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿وفي نسختها﴾ لا «وفيها»؟","answer":"﴿نسختها﴾ أي ما نُسخ وكتب فيها، فوجه النظر إلى مضمونها المثبت لا إلى جرم الألواح وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص613–620.","url":""}]},{"id":"s7-1035","number":1035,"surah":7,"verses":[154],"verseLabel":"الأعراف: 154","question":"لماذا جمع بين ﴿هدى ورحمة﴾؟","answer":"الهدى يبين طريق الحق، والرحمة ثمرة سلوكه من خير ونجاة؛ فجمعت الألواح الدلالة والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص613–620.","url":""}]},{"id":"s7-1036","number":1036,"surah":7,"verses":[154],"verseLabel":"الأعراف: 154","question":"لماذا خُص الهدى والرحمة بـ﴿للذين هم لربهم يرهبون﴾؟","answer":"الألواح هدى ورحمة في ذاتها، لكن الانتفاع الخاص بهما لمن يخاف ربه فيقبل أمره ويترك نهيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص613–620.","url":""}]},{"id":"s7-1037","number":1037,"surah":7,"verses":[154],"verseLabel":"الأعراف: 154","question":"ما سرّ تقديم ﴿لربهم﴾ على ﴿يرهبون﴾؟","answer":"تقديم ﴿لربهم﴾ للاختصاص والعناية: رهبتهم متوجهة إلى ربهم لا إلى سواه، ومن هذه الرهبة ينشأ امتثالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص613–620.","url":""}]},{"id":"s7-1038","number":1038,"surah":7,"verses":[154],"verseLabel":"الأعراف: 154","question":"لماذا جيء بضمير ﴿هم﴾؟","answer":"ضمير ﴿هم﴾ يقوي الحكم ويخص المنتفعين الكاملين بالرهبة، فيفصلهم عمن يقرأ ولا يتعظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص613–620.","url":""}]},{"id":"s7-1039","number":1039,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿واختار موسى قومه سبعين رجلًا﴾ من غير حرف جر؟","answer":"الفعل ﴿اختار﴾ تعدى بنفسه إلى المختارين بعد حذف ﴿من﴾، أي اختار من قومه سبعين، وفي الحذف اتصال مباشر بين الاختيار والمختارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1040","number":1040,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"لماذا حُدد العدد بسبعين رجلًا؟","answer":"حددهم بسبعين لأنهم كانوا نقباء ممثلين لسبطهم أو المختارين للميقات؛ والعدد بيان تاريخي لا رمز بلاغي يلزم اختراع سره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1041","number":1041,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿لميقاتنا﴾ فأضاف الميقات إلى الله؟","answer":"الإضافة تشرف الموعد وتبين أنه محدد بأمر الله للحضور والمناجاة، لا موعدًا وضعه موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1042","number":1042,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما أخذتهم الرجفة﴾، فجعل الرجفة آخذة؟","answer":"شبهت الرجفة بقوة تقبض عليهم وتستولي على أجسادهم، فكان الأخذ تصويرًا لشدة إحاطتها وتمكنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1043","number":1043,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"ما دلالة قول موسى: ﴿لو شئت أهلكتهم من قبل وإياي﴾؟","answer":"أظهر أن الله لو شاء إهلاكهم قبل المجيء لأهلكهم، أما وقوعه في الميقات فموضع خوف من شماتة القوم واتهام موسى؛ فهو تضرع لا اعتراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1044","number":1044,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"لماذا قدّم هلاكهم على نفسه: ﴿أهلكتهم من قبل وإياي﴾؟","answer":"قدمهم لأن الرجفة أخذتهم وكان الدعاء لأجلهم، ثم ضم نفسه إليهم في الضراعة وتحمل تبعة قيادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1045","number":1045,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"لماذا سأل: ﴿أتهلكنا بما فعل السفهاء منا﴾؟","answer":"الاستفهام استعطاف وتبرؤ من فعل السفهاء: أتهلك الجماعة بسبب من اقترف الجرم منها؟ وهو يعلم عدل الله، فيطلب الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1046","number":1046,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"لماذا وصف الفاعلين بـ﴿السفهاء منا﴾؟","answer":"وصفهم بالسفه لأن طلب الرؤية أو عبادة العجل صدر عن خفة عقل وجهل، و﴿منا﴾ تقر بالانتساب إليهم من غير تعميم الجرم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1047","number":1047,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿إن هي إلا فتنتك﴾ بالقصر؟","answer":"القصر يرد الأمر كله إلى اختبار الله وحده: هذه الحادثة ليست خارجة عن تدبيره، بل امتحان يكشف المواقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1048","number":1048,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"إلى ماذا يعود الضمير في ﴿إن هي إلا فتنتك﴾؟","answer":"يعود إلى الفتنة الواقعة، كعبادة العجل أو طلب الرؤية وما ترتب عليه من الرجفة؛ والتأنيث لمراعاة لفظ ﴿فتنة﴾ المفهوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1049","number":1049,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"لماذا جمع بين ﴿تضل بها من تشاء وتهدي من تشاء﴾؟","answer":"جمع الضدين لإظهار أن الفتنة الواحدة تكون سببًا لضلال من يعرض وهداية من يعتبر، وكل ذلك بمشيئة الله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1050","number":1050,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"ما سرّ تقديم الإضلال على الهداية؟","answer":"قدم الإضلال لأن المقام مقام قوم فتنوا ووقعت بهم الرجفة، ثم أتبعه بالهداية فتحًا لباب الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1051","number":1051,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"ما سرّ تقديم ضمير المخاطب في قوله: ﴿أنت ولينا﴾؟","answer":"تقديم ﴿أنت﴾ يفيد القصر والتوكيد: أنت وحدك متولي أمرنا وناصرنا، لا ملجأ لنا في هذه الفتنة إلا إليك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1052","number":1052,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"لماذا جمع بين ﴿فاغفر لنا وارحمنا﴾؟","answer":"المغفرة تزيل أثر الذنب، والرحمة تجلب العفو والخير؛ فطلب رفع الضر وإحلال الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1053","number":1053,"surah":7,"verses":[155],"verseLabel":"الأعراف: 155","question":"لماذا ختم بـ﴿وأنت خير الغافرين﴾ لا «أرحم الراحمين»؟","answer":"لأن المقام بدأ بطلب المغفرة في ﴿فاغفر لنا﴾، فناسبه ﴿خير الغافرين﴾؛ أي أوسعهم سترًا وتجاوزًا ولا يغفر الذنب حقيقة إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص621–640.","url":""}]},{"id":"s7-1054","number":1054,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿واكتب لنا في هذه الدنيا حسنة﴾، واستعار الكتابة للحسنة؟","answer":"الكتابة استعارة للإثبات والتقدير المحكم؛ أي قدر لنا حسنة ثابتة لا تزول كأنها مكتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1055","number":1055,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿في هذه الدنيا﴾ باسم الإشارة؟","answer":"الإشارة تحضر الدنيا القريبة المشاهدة وتقابلها بالآخرة الغائبة، وفيها اعتراف بقصر هذه الدار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1056","number":1056,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"لماذا نكّر ﴿حسنة﴾ في الدنيا وحذفها بعد ﴿وفي الآخرة﴾؟","answer":"نُكرت ﴿حسنة﴾ لتعم كل نعمة حسنة في الدنيا، وحذفت بعد ﴿وفي الآخرة﴾ لدلالة الأولى عليها، أي واكتب لنا حسنة في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1057","number":1057,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"ما دلالة قولهم: ﴿إنا هدنا إليك﴾، وما معنى «هدنا»؟","answer":"﴿هدنا﴾ أي رجعنا وتبنا إليك، فأعلنوا الانتقال من المعصية إلى ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1058","number":1058,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"ما صلة ﴿هدنا﴾ بتسمية اليهود؟","answer":"قيل اشتق اسم اليهود من قولهم ﴿هدنا إليك﴾ أي تبنا، وقيل من الانتساب إلى يهوذا؛ والآية تبين الدلالة اللغوية للهَوْد وهو الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1059","number":1059,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"لماذا جاء الجواب: ﴿عذابي أصيب به من أشاء ورحمتي وسعت كل شيء﴾؟","answer":"جاء الجواب موزعًا بين العدل والفضل: العذاب يصيب من تعلقت به المشيئة لحكمة، أما الرحمة فأصلها واسع ثم تكتب كتابة خاصة للمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1060","number":1060,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى في العذاب: ﴿أصيب به﴾، وفي الرحمة: ﴿وسعت﴾؟","answer":"﴿أصيب به﴾ يجعل العذاب محددًا يقع على من استحقه، أما ﴿وسعت﴾ فتصور الرحمة محيطة بكل شيء؛ فاختلاف الفعلين يرسم ضيق العقوبة وسعة الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1061","number":1061,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"ما سرّ تقديم العذاب على الرحمة هنا؟","answer":"قدم العذاب لأنه جواب لما نزل بهم من الرجفة وخوف الهلاك، ثم جاءت الرحمة أوسع وأغلب فاستقر بها الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1062","number":1062,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"لماذا نُسب العذاب والرحمة إلى ضمير المتكلم: ﴿عذابي... رحمتي﴾؟","answer":"الإضافة في ﴿عذابي﴾ و﴿رحمتي﴾ تثبت أن التصرف لله وحده، وتعظم الأمرين؛ مع تقديم الرحمة في السعة والوعد الخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1063","number":1063,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿ورحمتي وسعت كل شيء﴾، دون أن يقال: وأرحم من أشاء؟","answer":"بدل تقييد الرحمة بفئة من أول الجملة، صوّرها واسعة لكل شيء، ثم بين أن رحمة الآخرة الخاصة تكتب للمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1064","number":1064,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"كيف تجمع الآية بين سعة الرحمة لكل شيء وقوله: ﴿فسأكتبها للذين يتقون﴾؟","answer":"السعة العامة تشمل الخلق في الدنيا، والرحمة الخاصة الدائمة في الآخرة تُكتب للمتقين؛ فلا تعارض بين عموم الأثر وتخصيص الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1065","number":1065,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"لماذا عُبر عن الرحمة الخاصة بالكتابة: ﴿فسأكتبها﴾؟","answer":"الكتابة تفيد التثبيت والإيجاب بوعد لا يتخلف؛ فهي رحمة خاصة مقدرة للمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1066","number":1066,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"لماذا رتبت صفات مستحقي الرحمة: ﴿يتقون ويؤتون الزكاة والذين هم بآياتنا يؤمنون﴾؟","answer":"بدأ بالتقوى لأنها أصل الكف عن المعصية، ثم الزكاة مثال البذل العملي، ثم الإيمان بالآيات أصل التصديق الجامع للأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1067","number":1067,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"لماذا أعيد الموصول في ﴿والذين هم بآياتنا يؤمنون﴾؟","answer":"أعيد الموصول للاهتمام بالإيمان بالآيات وجعله صفة مستقلة جامعة، مع تقوية فصلها عما قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1068","number":1068,"surah":7,"verses":[156],"verseLabel":"الأعراف: 156","question":"ما سرّ تقديم ﴿بآياتنا﴾ على ﴿يؤمنون﴾؟","answer":"تقديم ﴿بآياتنا﴾ للعناية والاختصاص؛ إيمانهم متعلق بآيات الله كلها لا انتقاء فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–675.","url":""}]},{"id":"s7-1069","number":1069,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"لماذا وصف محمد ﷺ بـ﴿الرسول النبي الأمي﴾، وجمع هذه الأوصاف؟","answer":"﴿الرسول﴾ يبرز حمله الرسالة إلى الناس، و﴿النبي﴾ صلته بالوحي، و﴿الأمي﴾ قيام الحجة بأن ما جاء به ليس مكتسبًا من قراءة كتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1070","number":1070,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"ما سرّ تقديم ﴿الرسول﴾ على ﴿النبي﴾ هنا؟","answer":"قدم الرسول لأن المقام في اتباعه وتبليغه شريعة عامة، فالرسالة هي الوصف الأنسب قبل ذكر النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1071","number":1071,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"لماذا وُصف النبي ﷺ بـ﴿الأمي﴾؟","answer":"وصفه بالأمي لأنه لم يقرأ كتابًا ولم يكتب، فكان مجيئه بالقرآن دليلًا على الوحي، وهو أيضًا من الأمة الأمية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1072","number":1072,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿الذي يجدونه مكتوبًا عندهم﴾؟","answer":"﴿يجدونه﴾ يدل على أنهم يعثرون على صفته حاضرة ثابتة، و﴿مكتوبًا عندهم﴾ يلزمهم بما في الكتب التي بأيديهم لا بخبر بعيد عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1073","number":1073,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"لماذا جمع بين ﴿في التوراة والإنجيل﴾؟","answer":"ذكرا لأن البشارة به وصفاته ثبتت في كتابي اليهود والنصارى، فالحجة قائمة على الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1074","number":1074,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"لماذا رتبت وظائفه: ﴿يأمرهم بالمعروف وينهاهم عن المنكر ويحل لهم الطيبات ويحرم عليهم الخبائث﴾؟","answer":"بدأ بإصلاح المجتمع بالأمر والنهي، ثم بيان الحلال والحرام، ثم رفع التكاليف الشاقة؛ فانتقل من بناء القيم إلى التشريع ثم التخفيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1075","number":1075,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"لماذا عرّف ﴿المعروف﴾ و﴿المنكر﴾ و﴿الطيبات﴾ و﴿الخبائث﴾؟","answer":"التعريف للجنس أو للعهد في الشرائع: كل ما عرف حسنه شرعًا، وكل ما عرف قبحه، وما استطيب ونُزّه، وما خبث وحُرّم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1076","number":1076,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿ويضع عنهم إصرهم﴾، وصوّر الإصر كحمل؟","answer":"الإصر الثقل والتكليف الشاق؛ فصوّر الشرائع الثقيلة بحمل موضوع فوقهم، والرسول يرفعه عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1077","number":1077,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"لماذا أفرد ﴿إصرهم﴾ وجمع ﴿الأغلال﴾؟","answer":"الإصر مفرد لأنه اسم جنس للثقل الجامع، والأغلال جمعت لتعدد القيود والتكاليف التي كانت تكبلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1078","number":1078,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿والأغلال التي كانت عليهم﴾؟","answer":"شبهت التكاليف الشديدة بالأغلال المحيطة بالأعناق، و﴿كانت عليهم﴾ تدل على ثقلها واستعلائها قبل أن ترفعها الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1079","number":1079,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"لماذا رتبت الاستجابة: ﴿آمنوا به وعزروه ونصروه واتبعوا النور﴾؟","answer":"بدأوا بتصديقه في القلب، ثم تعظيمه وتوقيره، ثم نصر رسالته، ثم ملازمة القرآن والعمل به؛ فانتقل من الاعتقاد إلى النصرة والاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1080","number":1080,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"لماذا سمّى القرآن ﴿النور الذي أنزل معه﴾؟","answer":"سماه نورًا لأنه يكشف الحق من الباطل ويهدي في ظلمات الجهل، كما يكشف النور الطريق المحسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1081","number":1081,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿أنزل معه﴾ مع أن القرآن أُنزل إليه؟","answer":"﴿معه﴾ تفيد المصاحبة بين الرسول والقرآن في أداء الرسالة؛ أنزل القرآن مؤيدًا له ومقترنًا ببعثته، وإن كان التنزيل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1082","number":1082,"surah":7,"verses":[157],"verseLabel":"الأعراف: 157","question":"لماذا خُتم بـ﴿أولئك هم المفلحون﴾؟","answer":"اسم الإشارة مع ضمير الفصل وتعريف الخبر يفيد اختصاصهم بالفلاح الكامل؛ لأنهم جمعوا الإيمان والتعظيم والنصرة والاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص676–703.","url":""}]},{"id":"s7-1083","number":1083,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"لماذا انتقل إلى الأمر العام: ﴿قل يا أيها الناس﴾ بعد خطاب بني إسرائيل؟","answer":"انتقل من حكاية البشارة به في كتب أهل الكتاب إلى إعلان عموم رسالته لكل البشر، فلا يظن أنها خاصة بأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1084","number":1084,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"لماذا اجتمع النداء والتنبيه في ﴿يا أيها الناس﴾؟","answer":"﴿يا﴾ تستدعي البعيد أو الغافل، و﴿أيها﴾ تزيد التنبيه وتتيح وصف المنادى بـ﴿الناس﴾؛ فناسب النداءُ إعلانًا عالميًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1085","number":1085,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"لماذا أكد: ﴿إني رسول الله إليكم جميعًا﴾؟","answer":"أكد بـ﴿إن﴾ لمواجهة من ينكر عموم رسالته أو يقصرها على العرب، وقرر أنه رسول الله إلى المخاطبين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1086","number":1086,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿إليكم جميعًا﴾ مع أن ﴿الناس﴾ تفيد العموم؟","answer":"﴿جميعًا﴾ نص في استغراق أفراد الناس وتدفع احتمال إرادة طائفة مخصوصة من لفظ ﴿الناس﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1087","number":1087,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"لماذا وُصف الله بـ﴿الذي له ملك السماوات والأرض﴾ عقب عالمية الرسالة؟","answer":"من له ملك السماوات والأرض يملك إرسال رسول إلى جميع من فيهما؛ فعموم السلطان دليل مناسبة عموم الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1088","number":1088,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"ما سرّ تقديم ﴿له﴾ في ﴿له ملك السماوات والأرض﴾؟","answer":"تقديم ﴿له﴾ يفيد الاختصاص: الملك الحقيقي الكامل لله وحده، لا يشاركه فيه أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1089","number":1089,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"لماذا أعقب الملك بقوله: ﴿لا إله إلا هو﴾؟","answer":"إذا انفرد بالملك لزم انفراده بالعبادة، فجاء التوحيد نتيجة لتمام السلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1090","number":1090,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"لماذا جمع بين ﴿يحيي ويميت﴾؟","answer":"جمعهما لإثبات السلطان على طرفي الوجود الإنساني ومصيره، ومن يحيي ويميت وحده يستحق العبادة والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1091","number":1091,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"لماذا فرّع الأمر بالإيمان: ﴿فآمنوا بالله ورسوله﴾؟","answer":"الفاء تفرع وجوب الإيمان على البراهين السابقة: عموم الرسالة، وملك الله، ووحدانيته، وإحياؤه وإماتته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1092","number":1092,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"لماذا أعيد وصف الرسول بـ﴿النبي الأمي﴾ بعد الآية السابقة؟","answer":"أعيد الوصف لتعيين الرسول المأمور بالإيمان به، ولتذكير الناس بدليل أميته الذي سبق أن أقيم على أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1093","number":1093,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"ما سرّ التعبير في قوله تعالى عن الرسول: ﴿الذي يؤمن بالله وكلماته﴾؟","answer":"وصفه بأنه يؤمن بالله وكلماته ليبين أنه أول الممتثلين لما يدعو إليه، مصدق بجميع وحي الله لا آمر بما لا يعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1094","number":1094,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"لماذا جُمعت ﴿كلماته﴾؟","answer":"الجمع يشمل كلمات الله الكونية والشرعية وكتبه ووحيه المتعدد، وفيه كمال تصديق الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1095","number":1095,"surah":7,"verses":[158],"verseLabel":"الأعراف: 158","question":"لماذا ختم بـ﴿واتبعوه لعلكم تهتدون﴾ بعد الأمر بالإيمان؟","answer":"الإيمان أصل القلب، والاتباع أثره العملي؛ فليس المقصود مجرد التصديق، وإنما سلوك هديه، وبه ترجى الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص704–720.","url":""}]},{"id":"s7-1096","number":1096,"surah":7,"verses":[8],"verseLabel":"الأعراف: 158؛ الحديد: 7؛ التغابن: 8","question":"ما سرّ التعبير في قوله تعالى في الأعراف والتغابن: ﴿فآمنوا بالله ورسوله﴾ بالفاء، وفي الحديد: ﴿آمنوا بالله ورسوله﴾ بلا فاء؟","answer":"في الأعراف جاءت الفاء تفريعًا على صفات الله من الملك والتوحيد والإحياء والإماتة، وفي التغابن فاء فصيحة: إذا تبينت الحجج والعواقب فآمنوا؛ أما الحديد فانتقل من الاستدلال إلى الأمر المباشر بلا حاجة إلى تفريع ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص658، تحت الحديد: 7، في المقارنة بالأعراف: 158 والتغابن: 8.","url":""}]},{"id":"s7-1097","number":1097,"surah":7,"verses":[159],"verseLabel":"الأعراف: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن قوم موسى أمة﴾ بعد ذكر انحرافات بني إسرائيل؟","answer":"بعد ذكر انحرافات كثيرة لم يعمم الذم؛ استدرك بأن من قوم موسى جماعة ثابتة على الحق، إنصافًا للصالحين منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص721–726.","url":""}]},{"id":"s7-1098","number":1098,"surah":7,"verses":[159],"verseLabel":"الأعراف: 159","question":"لماذا نُكّرت ﴿أمة﴾؟","answer":"نُكرت للتبعيض والتعظيم: من قوم موسى جماعة متميزة بالاستقامة، لا القوم كلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص721–726.","url":""}]},{"id":"s7-1099","number":1099,"surah":7,"verses":[159],"verseLabel":"الأعراف: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿يهدون بالحق﴾ لا «يهتدون»؟","answer":"﴿يهدون﴾ متعدٍّ؛ فهم لا يكتفون بالاهتداء في أنفسهم، بل يرشدون غيرهم إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص721–726.","url":""}]},{"id":"s7-1100","number":1100,"surah":7,"verses":[159],"verseLabel":"الأعراف: 159","question":"لماذا عُدّيت الهداية بـ﴿الباء﴾: ﴿بالحق﴾؟","answer":"الباء للملابسة أو الاستعانة؛ أي يهدون ملتبسين بالحق وجاعلينه معيار هدايتهم، لا بالهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص721–726.","url":""}]},{"id":"s7-1101","number":1101,"surah":7,"verses":[159],"verseLabel":"الأعراف: 159","question":"لماذا كرر الحق ضميرًا في ﴿وبه يعدلون﴾؟","answer":"أعيد الحق ضميرًا وقدّم في ﴿وبه يعدلون﴾ لإبراز أنه الأداة والمعيار الذي يقيمون به العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص721–726.","url":""}]},{"id":"s7-1102","number":1102,"surah":7,"verses":[159],"verseLabel":"الأعراف: 159","question":"لماذا جمع بين الهداية والعدل؟","answer":"الهداية تبليغ الحق والدلالة عليه، والعدل تنفيذه في الحكم والعمل؛ فجمعوا العلم بالحق وتطبيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص721–726.","url":""}]},{"id":"s7-1103","number":1103,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿وقطعناهم اثنتي عشرة أسباطًا أممًا﴾، واستعمل «قطعنا» للتقسيم؟","answer":"﴿قطعناهم﴾ أي قسمناهم جماعات متميزة، فصوّر انفصال الأسباط بعضهم عن بعض مع بقائهم من أصل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1104","number":1104,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا أُنّث العدد في ﴿اثنتي عشرة﴾ مع ﴿أسباطًا﴾ المذكر؟","answer":"التمييز الملحوظ هو «فرقة» أو «قطعة» مؤنثة: اثنتي عشرة فرقة، أما ﴿أسباطًا﴾ فبدل أو بيان للفرق، لذلك جاء العدد مؤنث الصيغة الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1105","number":1105,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا جمع بين ﴿أسباطًا﴾ و﴿أممًا﴾؟","answer":"﴿أسباطًا﴾ تبين أن التقسيم بحسب الأنساب، و﴿أممًا﴾ تبين أن كل سبط صار جماعة مستقلة لها نظامها وشؤونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1106","number":1106,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿وأوحينا إلى موسى إذ استسقاه قومه﴾ بدل «لما استسقوه»؟","answer":"﴿إذ﴾ تستحضر لحظة طلب القوم الماء سببًا للوحي، بخلاف «لما» التي تبرز التعقيب الزمني؛ فالمقام حكاية النعمة في وقت الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1107","number":1107,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا أضيف القوم إلى موسى: ﴿قومه﴾؟","answer":"الإضافة تربطهم بنبيهم الذي طلبوا منه واستسقى لهم، وتذكر بمسؤوليته عنهم وصلتهم برسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1108","number":1108,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿أن اضرب بعصاك الحجر﴾، وجُعل الضرب سببًا لخروج الماء؟","answer":"جعل الضرب بالعصا سببًا ظاهرًا لخروج الماء مع أن القدرة لله، لتظهر المعجزة من اجتماع سبب لا يخرج الماء عادة بنتيجة خارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1109","number":1109,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا عُرّف ﴿الحجر﴾؟","answer":"التعريف للعهد؛ هو الحجر المعروف الذي أُمر موسى بضربه، أو الجنس بحيث تكون المعجزة في أي حجر عُيّن.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1110","number":1110,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿فانبجست﴾، وفي البقرة: ﴿فانفجرت﴾؟","answer":"الانبجاس ابتداء خروج الماء أو خروجه بسعة دون غاية الانفجار، أما الانفجار فأقوى؛ وناسب البقرة مقام تعداد النعم فذكر الأكمل، والأعراف مقام سرد الأحداث.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1111","number":1111,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿منه اثنتا عشرة عينًا﴾ بعد عدد الأسباط نفسه؟","answer":"وافق عدد العيون عدد الأسباط، فجعل لكل جماعة عينًا مستقلة، منعًا للتزاحم والنزاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1112","number":1112,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿قد علم كل أناس مشربهم﴾؟","answer":"﴿قد﴾ تحقق العلم، و﴿كل أناس﴾ تفيد أن كل جماعة عرفت موردها المخصص؛ فانتظمت القسمة بلا اختلاط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1113","number":1113,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿كل أناس﴾ لا «كل سبط»؟","answer":"﴿أناس﴾ تبرز البشر المنتفعين بالماء لا مجرد وحدتهم النسبية، وتشمل أفراد كل سبط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1114","number":1114,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿وظللنا عليهم الغمام﴾، فجعل الغمام مظلة؟","answer":"جعل الغمام فوقهم يحجب حر الشمس، فالفعل يصور السحاب مظلة ممتدة بعناية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1115","number":1115,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا اختير ﴿الغمام﴾ لا «السحاب»؟","answer":"الغمام سحاب رقيق أبيض يستر الشمس من غير ظلمة السحاب الثقيل، فكان أنسب للظل والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1116","number":1116,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا جمع بين الماء والظل والمن والسلوى في آية واحدة؟","answer":"جمعت مقومات بقائهم في الصحراء: الماء للشرب، والغمام للوقاية، والمن والسلوى للطعام؛ فتكامل الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1117","number":1117,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنزلنا عليهم المن والسلوى﴾؟","answer":"﴿أنزلنا﴾ يفيد أن الرزق جاءهم من فوق من غير كسب معتاد، و﴿عليهم﴾ تشعر بإحاطته وكثرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1118","number":1118,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا جاء الأمر: ﴿كلوا من طيبات ما رزقناكم﴾؟","answer":"الأمر للإباحة والامتنان: انتفعوا بالحلال المستطاب الذي رزقكم الله، وفي إضافة الرزق إليه تذكير بالمنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]}]);
